// Five original hard AgilePM v3 Foundation papers (6–10).
// Official APMG style + syllabus weighting. Not official APMG items.

export const FINAL_MOCKS_B = [
  {
    id: 'final6',
    title: 'Final Paper 6',
    questions: [
      { id: 'F6Q1', topic: 'KC', q: 'Within the Agile Business Consortium\'s Framework for Business Agility, which segment does AgilePM occupy?', options: ['The change segment', 'The culture segment', 'The leadership segment', 'The governance-only segment'], correct: 'The change segment', explain: 'AgilePM sits in the FBA change segment, giving a structured yet adaptive approach to agile projects and product development (Ch.1).' },
      { id: 'F6Q2', topic: 'KC', q: 'Identify the missing year. The DSDM Consortium rebranded as the Agile Business Consortium in [ ? ].', options: ['2016', '2010', '1994', '2001'], correct: '2016', explain: 'The professional body rebranded from DSDM Consortium to Agile Business Consortium in 2016 (Ch.1).' },
      { id: 'F6Q3', topic: 'KC', q: 'Which of the following statements about Scientific Management (Taylorism) are true?\n1. It promoted efficiency, automation, economies of scale and strict procedure-following\n2. Staff were often not expected to understand the reasoning behind the rules they followed\n3. AgilePM recommends it as the operating model for VUCA environments\n4. In extreme cases employees were treated like machines', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Taylorism valued procedure over understanding; AgilePM rejects that model because VUCA needs people who can think, assess and adapt (2.1).' },
      { id: 'F6Q4', topic: 'KC', q: 'Consider the following statements about Product Lifecycle Management (PLM).\n1. Latent value is realised only when the product is actually in use\n2. PLM looks across ideation, development, distribution, servicing and retirement', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'PLM covers the whole product life; a solution-focused view exists so latent value is captured once the product is used (2.2).' },
      { id: 'F6Q5', topic: 'KC', q: 'Which statement best distinguishes project management from product development in AgilePM?', options: ['Product development focuses on what the product must become and how it is built; project management organises the environment so that value is actually achieved once delivered', 'Project management owns the Product Backlog; product development owns the Business Case', 'Product development fixes time and cost; project management fixes features', 'They are interchangeable labels for the same set of accountabilities'], correct: 'Product development focuses on what the product must become and how it is built; project management organises the environment so that value is actually achieved once delivered', explain: 'Product development is the what/how of the product; project management oversees who, why, when and where so value is realised (2.2–2.3).' },
      { id: 'F6Q6', topic: 'SC', q: 'Which of the following are ways the Scrum Master serves the organisation?\n1. Leading, training and coaching the organisation in Scrum adoption\n2. Ordering the Product Backlog when the Product Owner is absent\n3. Helping employees and stakeholders enact empirical approaches\n4. Removing barriers between stakeholders and Scrum Teams', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The Scrum Master coaches adoption and empiricism and removes barriers; backlog ordering remains a Product Owner accountability (3.4).' },
      { id: 'F6Q7', topic: 'SC', q: 'During Topic Three of Sprint Planning, selected Product Backlog items are typically decomposed into work items of what size?', options: ['One day or less', 'One week or less', 'The remainder of the Project Increment', 'Whatever size the Project Manager assigns'], correct: 'One day or less', explain: 'Topic Three asks how the chosen work will get done; items are often broken into work of one day or less (3.5).' },
      { id: 'F6Q8', topic: 'SC', q: 'Identify the missing words. Lean thinking, on which Scrum is founded together with empiricism, reduces waste and focuses on [ ? ].', options: ['the essentials', 'comprehensive documentation', 'contractual remedies', 'a single-figure estimate'], correct: 'the essentials', explain: 'Scrum is founded on empiricism and lean thinking; lean thinking reduces waste and focuses on essentials (3.2).' },
      { id: 'F6Q9', topic: 'SC', q: 'Consider the following statements about the Sprint Review.\n1. It is the last event of the Sprint\n2. The Scrum Team should treat it as a working session rather than limiting it to a presentation', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The Review is the second-to-last event (the Retrospective follows). It is a working session, not a presentation (3.5).' },
      { id: 'F6Q10', topic: 'SC', q: 'Which of the following correctly describe Scrum artefacts and their commitments?\n1. Delivery Plan — Solution Goal\n2. Product Backlog — Product Goal\n3. Sprint Backlog — Sprint Goal\n4. Product Increment — Definition of Done', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The three Scrum artefacts and commitments are PB/Product Goal, SB/Sprint Goal and Increment/DoD. The Delivery Plan is an AgilePM project artefact (3.6).' },
      { id: 'F6Q11', topic: 'SC', q: 'What happens to a Product Backlog item that does not meet the Definition of Done by the end of the Sprint?', options: ['It cannot be released or even presented at the Sprint Review and returns to the Product Backlog', 'It may still be presented at the Sprint Review if stakeholders agree', 'It is automatically added to the next Sprint Backlog', 'It is converted into a Could Have on the Solution Backlog'], correct: 'It cannot be released or even presented at the Sprint Review and returns to the Product Backlog', explain: 'An Increment is born only when a PBI meets the DoD; unfinished items return to the Product Backlog (3.6).' },
      { id: 'F6Q12', topic: 'AF', q: 'Identify the missing words. Common sense in AgilePM means using logical thinking and practical judgment instead of introducing [ ? ].', options: ['unnecessary complexity', 'MoSCoW priorities', 'timeboxes', 'facilitated workshops'], correct: 'unnecessary complexity', explain: 'Common sense and pragmatism underpin the framework; common sense avoids unnecessary complexity (4.1).' },
      { id: 'F6Q13', topic: 'AF', q: 'Under \'Focus on the Business Need\', who defines and communicates the project vision, and what must the Project Manager ensure?', options: ['The Business Visionary defines and communicates the vision; the Project Manager ensures goals are clearly defined and priorities are realistic', 'The Project Manager writes the vision; the Business Sponsor estimates story points', 'The Product Owner owns the Business Case; the Scrum Master sets MoSCoW priorities', 'The Solution Architect defines the vision; the Business Sponsor facilitates Daily Scrums'], correct: 'The Business Visionary defines and communicates the vision; the Project Manager ensures goals are clearly defined and priorities are realistic', explain: 'Principle 1: the BV owns the vision; the PM does not create the Business Case but keeps goals and priorities realistic (4.3).' },
      { id: 'F6Q14', topic: 'AF', q: 'Consider the following statements about traditional time or budget contingency.\n1. Sponsors often hesitate to set aside formal contingency because of Parkinson\'s Law\n2. Once planned contingency runs out, control of the remaining variables typically becomes easier', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Parkinson\'s Law makes sponsors wary of spare time; when contingency is exhausted, control of variables becomes harder, not easier (4.2).' },
      { id: 'F6Q15', topic: 'AF', q: 'Which three things must high-level plans, designs and standards define under \'Demonstrate Control\'?', options: ['Who will be blamed, which contract clause applies, and the audit trail', 'What needs to be done, how it will be achieved, and when it will be delivered', 'The Product Goal, the Sprint Goal and the Definition of Ready', 'The PAQ score, the Cone of Uncertainty band, and the RACI chart'], correct: 'What needs to be done, how it will be achieved, and when it will be delivered', explain: 'Principle 8 requires high-level plans, designs and standards to define what, how and when (4.3).' },
      { id: 'F6Q16', topic: 'AF', q: 'How does AgilePM specifically help the Scrum Master, beyond what Scrum alone provides?', options: ['It lets the Scrum Master cancel a Sprint if the Product Goal looks at risk', 'It gives a way to communicate with business leaders and project managers so that agile teams get the support they need', 'It transfers Product Backlog ordering to the Scrum Master on multi-team projects', 'It replaces the Daily Scrum with a Project Sprint Review'], correct: 'It gives a way to communicate with business leaders and project managers so that agile teams get the support they need', explain: 'AgilePM helps the Scrum Master communicate upwards so team performance is supported by the wider project (4.4).' },
      { id: 'F6Q17', topic: 'IN', q: 'Which of the following is the exact wording of an Agile Business Consortium principle of agile leadership?', options: ['Leaders replace ecosystems with hierarchies', 'Leaders favour ecosystems over hierarchies', 'Leaders centralise all day-to-day decisions', 'Leaders avoid developing other leaders'], correct: 'Leaders favour ecosystems over hierarchies', explain: 'One of the nine principles is the exact wording \'Leaders favour ecosystems over hierarchies\' (5.1).' },
      { id: 'F6Q18', topic: 'IN', q: 'Which of the following are among the nine Principles of Agile Leadership, in their exact wording?\n1. Leaders embrace and enable team and individual mastery\n2. Leaders foster team accountability\n3. Leaders ensure clarity of purpose\n4. Leaders replace purpose with a detailed Gantt chart', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The first three are exact leadership principles; replacing purpose with a Gantt chart is not (5.1).' },
      { id: 'F6Q19', topic: 'IN', q: 'Identify the missing words. Geoff Watts\' two commandments for a Scrum Master are \'First ask the team\' and \'[ ? ]\'.', options: ['Protect the Sprint Goal at all costs', 'Make yourself redundant', 'Estimate the Product Backlog', 'Report daily to the Business Sponsor'], correct: 'Make yourself redundant', explain: 'Watts\' commandments are \'First ask the team\' and \'Make yourself redundant\' (5.3.6).' },
      { id: 'F6Q20', topic: 'IN', q: 'Consider the following statements about Business Analysts in AgilePM.\n1. At the strategic level they assist executives in defining and shaping business strategies that impact the whole organisation\n2. At the operational level they define detailed acceptance criteria so delivered products meet requirements and align with the Definition of Done', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'BA work spans C-suite strategy and operational acceptance criteria; a BA may also work as a Developer supporting backlog management (5.4).' },
      { id: 'F6Q21', topic: 'IN', q: 'A person helps shape the project during Feasibility by giving specialist business input on scenarios and regulatory compliance, then later becomes a Product Owner. Which Advisor role were they fulfilling in Feasibility?', options: ['Process Advisor', 'Business Advisor', 'Solution Advisor', 'Workshop Facilitator only'], correct: 'Business Advisor', explain: 'Business Advisors collaborate with value-ownership roles; the same person may later become a Product Owner or Business Ambassador (5.4).' },
      { id: 'F6Q22', topic: 'IN', q: 'Which of the following correctly describe Advisor roles?\n1. Solution Advisors collaborate with solution-delivery roles and may later become Developers\n2. Process Advisors collaborate with organisation-enablement roles; an Agile Coach is a typical example\n3. Financial Advisor is a named third Advisor role alongside Business and Solution Advisors\n4. A Workshop Facilitator is an example of a Process Advisor', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three Advisor roles are Business, Solution and Process — there is no Financial Advisor role (5.4).' },
      { id: 'F6Q23', topic: 'IN', q: 'Which exact leadership principle is demonstrated when a leader deliberately grows other people\'s capacity to lead rather than creating a following?', options: ['Leaders are stewards of organisational values', 'Leaders develop new leaders (not followers)', 'Leaders enable agility to maximise value and impact', 'Leaders favour ecosystems over hierarchies'], correct: 'Leaders develop new leaders (not followers)', explain: 'Agile leaders develop new leaders, not followers — exact principle wording (5.1).' },
      { id: 'F6Q24', topic: 'CC', q: 'Jim Highsmith\'s warning about confusing artefacts with professionalism completes: \'Documentation is not understanding, process is not discipline, [ ? ] is not skill.\'', options: ['governance', 'formality', 'leadership', 'estimation'], correct: 'formality', explain: 'The Highsmith quote ends \'formality is not skill\' (6.4 / 12.1).' },
      { id: 'F6Q25', topic: 'CC', q: 'Specialists from several disciplines keep talking past one another because each uses their own jargon. What does AgilePM recommend when a common everyday language is not practical?', options: ['Replace all workshops with email threads', 'Keep a glossary of key terms and their definitions', 'Ask the Project Manager to translate every conversation', 'Mandate that only the Solution Architect may speak'], correct: 'Keep a glossary of key terms and their definitions', explain: 'Diverse teams should use straightforward language; if that is impractical, a glossary prevents misunderstanding (6.3).' },
      { id: 'F6Q26', topic: 'CC', q: 'On the Aligned Autonomy Matrix, which mappings are correct?\n1. Low alignment and high autonomy — Bureaucratic organisation (indifferent culture)\n2. High alignment and high autonomy — Innovative organisation (collaborative culture)\n3. High alignment and low autonomy — Authoritative organisation (authoritarian culture)\n4. Low alignment and low autonomy — Bureaucratic organisation (indifferent culture)', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Low alignment + high autonomy is entrepreneurial/chaotic, not bureaucratic. Bureaucratic is low/low (Fig. 6.1).' },
      { id: 'F6Q27', topic: 'CC', q: 'Consider the following statements about the Power/Interest Grid.\n1. A stakeholder with high power and high interest should be closely engaged\n2. A stakeholder with low power and high interest should be monitored with minimum effort', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'High power/high interest = closely engage. Low power/high interest = keep informed; minimum-effort monitor is low/low (Fig. 6.2).' },
      { id: 'F6Q28', topic: 'PR', q: 'What bounds a Project Increment Timebox at each end?', options: ['A Daily Scrum at the start and a Sprint Review at the end', 'Contract signature at the start and a Benefits Assessment at the end', 'A revisit of the Foundations Phase at the start and a Project Increment Review at the end', 'PAQ completion at the start and Cone of Uncertainty closure at the end'], correct: 'A revisit of the Foundations Phase at the start and a Project Increment Review at the end', explain: 'Project Increment timeboxes are bound by Foundations (start) and a Project Increment Review (end) (7.1).' },
      { id: 'F6Q29', topic: 'PR', q: 'Which of the following are timebox types AgilePM considers?\n1. The overall Project Timebox\n2. The Cone of Uncertainty Timebox\n3. The Project Increment Timebox\n4. Delivery Timeboxes (Sprints)', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The three timeboxes are Project, Project Increment and Delivery (Sprint). There is no Cone timebox (7.1).' },
      { id: 'F6Q30', topic: 'PR', q: 'Identify the missing words. Delivery Teams should aim for a \'[ ? ]\' slice that contains all required elements so the increment can actually be used.', options: ['horizontal technology', 'contractual', 'vertical or Done product', 'Feasibility-only'], correct: 'vertical or Done product', explain: 'A vertical/Done slice includes UI, logic and data (or equivalent). A horizontal layer delays usable value (7.5).' },
      { id: 'F6Q31', topic: 'PR', q: 'Consider the following statements about the Realisation Phase.\n1. The Business Visionary is responsible for embedding the solution so benefits can be realised\n2. The Business Sponsor is accountable for the return on investment', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'BV embeds the solution; BS remains accountable for RoI (7.7).' },
      { id: 'F6Q32', topic: 'PR', q: 'At what point does AgilePM treat the Deployment Phase as finished?', options: ['When the Sprint Backlog is empty', 'When the PAQ is first completed', 'When the Solution Increment has been introduced into operational use and has reached a steady state from which it can consistently provide business value', 'As soon as coding of the first Product Increment starts'], correct: 'When the Solution Increment has been introduced into operational use and has reached a steady state from which it can consistently provide business value', explain: 'Deployment ends when the increment is in operational use and stable enough to yield value (7.6).' },
      { id: 'F6Q33', topic: 'ES', q: 'Which of the following are true of MoSCoW and the Business Case?\n1. Worst-case benefits are based on just the Must Haves\n2. Expected-case benefits are based on Must Haves plus Should Haves\n3. Cost estimates should cover only the Must Have subset\n4. Best-case benefits include Must, Should and Could Haves', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Costs cover the full scope; benefits use Must+Should as expected, Musts as worst, and Must+Should+Could as best (9.7).' },
      { id: 'F6Q34', topic: 'ES', q: 'Which agile coach is credited with inventing the widely used \'As a / I want / So that\' User Story template?', options: ['Ken Schwaber', 'Barry Boehm', 'Rachel Davies', 'Frederick Taylor'], correct: 'Rachel Davies', explain: 'Rachel Davies invented the widely used As a / I want / So that format in the early 2000s (8.2.3).' },
      { id: 'F6Q35', topic: 'ES', q: 'Identify the missing word. Estimating by analogy is also known as [ ? ] estimating.', options: ['bottom-up', 'commitment-based', 'comparative', 'absolute-hour'], correct: 'comparative', explain: 'Analogy-based estimating is also called comparative estimating (8.3.3).' },
      { id: 'F6Q36', topic: 'ES', q: 'Consider the following statements about INVEST.\n1. Independent means the story is not dependent on other stories, which enables replanning\n2. Small (Enough) means the story is small enough to be completed inside the relevant timebox (project, increment or Sprint)', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'INVEST: Independent enables replanning; Small (Enough) is relative to the timebox in play (8.2.3.4).' },
      { id: 'F6Q37', topic: 'ES', q: 'A change that widens the list of requirements (adding, removing or significantly altering items) is called what, and how should it be handled?', options: ['A change in depth, absorbed silently by Could Haves', 'A Definition of Ready failure, which cancels the Sprint', 'A PAQ disagreement, which always stops the project', 'Scope creep (a change in breadth), which must be formally controlled'], correct: 'Scope creep (a change in breadth), which must be formally controlled', explain: 'Breadth changes are scope creep and need formal control; depth changes use MoSCoW contingency (8.2.4).' },
      { id: 'F6Q38', topic: 'ES', q: 'Which of the following are suggested Definition of Ready criteria?\n1. The Business Sponsor has estimated the story in hours\n2. The item has a clear outcome and understood scope\n3. Acceptance Criteria are agreed\n4. Dependencies and risks are understood', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'DoR includes clear outcome, agreed AC and understood dependencies. Developers estimate; the Sponsor does not (8.2.3.5).' },
      { id: 'F6Q39', topic: 'PC', q: 'What is the recommended duration for Cross-Team Refinement?', options: ['15 minutes, matching the Daily Scrum', 'A full day every Project Increment', '8 hours, matching Sprint Planning', '1–3 hours'], correct: '1–3 hours', explain: 'CTR is typically 1–3 hours, at least once per Sprint; teams should experiment (10.2.3.6).' },
      { id: 'F6Q40', topic: 'PC', q: 'Identify the missing words. Charts such as burn-down, burn-up and cumulative flow are working tools for visibility; they should not be used to [ ? ].', options: ['inspect progress', 'support adaptation', 'make remaining work visible', 'judge or compare team performance'], correct: 'judge or compare team performance', explain: 'Charts support empiricism for that team; they must not be used to judge or compare performance (10.2.3.5).' },
      { id: 'F6Q41', topic: 'PC', q: 'Which of the following are true of Project Sprint Planning?\n1. The Agile Project Manager facilitates, with the Product Owner and Delivery Team representatives present\n2. It mirrors all three topics of standard Sprint Planning, including detailed task breakdown\n3. An over-arching Project Sprint Goal may be created but is optional\n4. Other Project Roles and Advisors may attend to guide and support', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Project Sprint Planning mirrors the first two topics (why/what). How/tasking is Delivery Team Sprint Planning (10.2.3.4).' },
      { id: 'F6Q42', topic: 'PC', q: 'Consider the following statements about the Project Sprint Retrospective.\n1. The Business Sponsor and Business Visionary attend as the primary audience\n2. After team retrospectives, the joint project retrospective is for the whole Project Organisation except the Business Sponsor and Business Visionary', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The joint Project Sprint Retrospective excludes BS and BV; it is not run as a report to those two roles (10.2.3.8).' },
      { id: 'F6Q43', topic: 'PC', q: 'Once a solution is in place, which role is accountable for the accompanying business change and for benefits realisation that should follow?', options: ['The Scrum Master', 'The Developers', 'The Process Advisor', 'The Business Visionary'], correct: 'The Business Visionary', explain: 'The BV is accountable for wider business change and benefits realisation; the PM ensures realisation activities are planned (10.2.3.10).' },
      { id: 'F6Q44', topic: 'RK', q: 'Which of the following correctly assign risk ownership?\n1. Value Ownership-based risk — Business Visionary\n2. Solution Delivery-based risk — Solution Architect\n3. Delivery Enablement risk (organisation, schedule, dependencies) — Project Manager\n4. All three categories of risk — Product Owner alone', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'BV, SA and PM own the three risk categories respectively; the PO does not own all three (11.1).' },
      { id: 'F6Q45', topic: 'RK', q: 'Consider the following statements about PAQ Statement 2.\n1. The project needs strong, proactive ownership from the Business Sponsor and Business Visionary\n2. If reorganisation and coaching fail to engage the Business Visionary, AgilePM\'s suggested action is to refuse to continue until ownership is resolved', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Without committed value-ownership the team is forced into assumptions; if the BV cannot be engaged, do not continue (11.2.2.2).' },
      { id: 'F6Q46', topic: 'RK', q: 'PAQ Statement 13 expects Developers to be allocated at an appropriate, consistent level. What should be avoided if availability is highly unpredictable?', options: ['Planning Sprint Goals around known availability', 'Gaining commitment to the ways of working in the MAD and DAD', 'Discussing gaps with the Business Sponsor', 'Extending Sprint durations to compensate for part-time allocation'], correct: 'Extending Sprint durations to compensate for part-time allocation', explain: 'Do not extend Sprints to paper over availability; that reduces focus. Plan around availability or find better staffing (11.2.2.13).' },
      { id: 'F6Q47', topic: 'GV', q: 'Identify the missing words. If a Business Sponsor insists on a single-figure estimate, [ ? ] must choose it from the range provided.', options: ['the estimator', 'the Scrum Master', 'the Developers by vote', 'the Business Sponsor themselves'], correct: 'the Business Sponsor themselves', explain: 'The Sponsor, not the estimator, selects any single figure from the range after discussing understanding, assumptions and risk (12.3.1).' },
      { id: 'F6Q48', topic: 'GV', q: 'Who is Responsible and who is Accountable for the Management Approach Definition (MAD)?', options: ['Responsible: Business Visionary; Accountable: Solution Architect', 'Responsible: Product Owner; Accountable: Scrum Master', 'Responsible: Solution Architect; Accountable: Project Manager', 'Responsible: Project Manager; Accountable: Business Sponsor'], correct: 'Responsible: Project Manager; Accountable: Business Sponsor', explain: 'MAD: R = Project Manager, A = Business Sponsor; it is baselined at the end of Foundations (App. A).' },
      { id: 'F6Q49', topic: 'GV', q: 'Consider the following statements about financial-governance artefacts.\n1. The Feasibility Assessment is written only after Realisation has measured benefits\n2. Benefits Assessment is a Pre-Project forecast that replaces the Business Case', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Neither 1 nor 2 is true', explain: 'Feasibility Assessment is the early viability view; Benefits Assessment records realised benefits in operation — neither statement is correct (12.3.2).' },
      { id: 'F6Q50', topic: 'GV', q: 'Which artefacts can be customised to show regulatory compliance?', options: ['The Daily Scrum notes, the coffee-card from Planning Poker, and the PAQ cover sheet', 'Only the Product Increment, because process quality is never evidenced', 'Only the Terms of Reference, because later artefacts must stay informal', 'The Solution Architecture Definition, Sprint Review Records and Project Review Reports'], correct: 'The Solution Architecture Definition, Sprint Review Records and Project Review Reports', explain: 'SAD, Sprint Review Records and Project Review Reports can be tailored as auditable compliance evidence (12.2).' },
    ],
  },
  {
    id: 'final7',
    title: 'Final Paper 7',
    questions: [
      { id: 'F7Q1', topic: 'KC', q: 'Which characteristic of agility is most directly aimed at the reality that cause and effect are no longer clear?', options: ['People and systems that are flexible, adaptable, thoughtful, collaborative and good at solving problems', 'Treating employees as operators of fixed procedures', 'Locking the design before any increment is used', 'Measuring progress solely as percentage complete against a baseline Gantt chart'], correct: 'People and systems that are flexible, adaptable, thoughtful, collaborative and good at solving problems', explain: 'Complexity in VUCA is about unclear cause and effect; people who can think and adapt cope best (2.1.2).' },
      { id: 'F7Q2', topic: 'KC', q: 'Identify the missing word. In VUCA, [ ? ] means information or situations can have more than one possible meaning.', options: ['Ambiguity', 'Volatility', 'Uncertainty', 'Complexity'], correct: 'Ambiguity', explain: 'Ambiguity is multiple possible meanings; uncertainty is difficulty predicting; complexity is interconnected parts (2.1.2).' },
      { id: 'F7Q3', topic: 'KC', q: 'Which of the following are characteristics AgilePM says agile documents should have?\n1. Light touch rather than overly detailed or controlling\n2. Guiding rather than rigid or restrictive\n3. Hidden from anyone outside the Delivery Team\n4. Easily visible and clearly understood by the stakeholders involved', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Agile documents are light-touch, guiding, visible and understood — not hidden (2.1.3).' },
      { id: 'F7Q4', topic: 'KC', q: 'Consider the following statements about why the last responsible moment is more efficient.\n1. Near-future predictions are more reliable than long-range detailed plans\n2. Decisions made later are often better because teams have tested assumptions and learned', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Deferring detail to the last responsible moment reduces wasted documentation and improves decisions (2.4).' },
      { id: 'F7Q5', topic: 'KC', q: 'To honour the Manifesto value that ranks individuals and interactions above processes and tools, what must each person be able to demonstrate?', options: ['That they be prepared and willing to contribute, capable and confident in the job, and empowered (trusted, willing, authorised) to decide and act', 'That they wait for written authority before any conversation', 'That they replace all processes with informal chat', 'That they treat the contract as the only source of truth'], correct: 'That they be prepared and willing to contribute, capable and confident in the job, and empowered (trusted, willing, authorised) to decide and act', explain: 'The left-hand value still needs capable, willing, empowered people — not the absence of all process (2.1.3).' },
      { id: 'F7Q6', topic: 'SC', q: 'Which of the following are Developer accountabilities in Scrum?\n1. Cancelling the Sprint if the Product Goal looks obsolete\n2. Creating a plan for the Sprint (the Sprint Backlog)\n3. Instilling quality by adhering to the Definition of Done\n4. Adapting their plan each day toward the Sprint Goal', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Only the Product Owner can cancel a Sprint, and only if the Sprint Goal is obsolete (3.4–3.5).' },
      { id: 'F7Q7', topic: 'SC', q: 'What must be true of the current Product Goal before the Scrum Team takes on the next one?', options: ['It must be fulfilled or abandoned', 'It must be converted into a Solution Goal by the Business Sponsor', 'It must be added to the Definition of Done', 'It must be estimated in hours by the Project Manager'], correct: 'It must be fulfilled or abandoned', explain: 'The Product Goal is the long-term objective and must be fulfilled or abandoned before the next is taken on (3.6).' },
      { id: 'F7Q8', topic: 'SC', q: 'Identify the missing words. Adaptation should occur as soon as possible to minimise further deviation; it becomes more difficult when people are not [ ? ].', options: ['empowered or self-managing', 'certified as Scrum Masters', 'co-located in one building', 'using a burn-down chart'], correct: 'empowered or self-managing', explain: 'Inspection without adaptation is pointless; adaptation needs empowered, self-managing people (3.2).' },
      { id: 'F7Q9', topic: 'SC', q: 'Consider the following statements about the Daily Scrum.\n1. It is a 15-minute event for the Developers, held at the same time and place every working day\n2. It is the only time Developers are allowed to adjust their plan', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'The Daily Scrum inspects progress to the Sprint Goal; Developers often meet throughout the day as well (3.5).' },
      { id: 'F7Q10', topic: 'SC', q: 'Which of the following are true of Scrum events for a one-month Sprint?\n1. Sprint Planning is timeboxed to a maximum of 8 hours\n2. The Daily Scrum is timeboxed to a maximum of 45 minutes\n3. The Sprint Review is timeboxed to a maximum of 4 hours\n4. The Sprint Retrospective is timeboxed to a maximum of 3 hours', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Daily Scrum is 15 minutes, not 45. The other three maxima are correct (3.5).' },
      { id: 'F7Q11', topic: 'SC', q: 'How does the Scrum Master serve the Product Owner?', options: ['By helping find techniques for effective Product Goal definition, empirical product planning and stakeholder collaboration', 'By ordering the Product Backlog whenever the Product Owner is in a meeting', 'By cancelling Sprints that look challenging', 'By presenting the Increment so the Product Owner need not attend the Review'], correct: 'By helping find techniques for effective Product Goal definition, empirical product planning and stakeholder collaboration', explain: 'The Scrum Master serves the PO with techniques and collaboration — not by taking PO decisions (3.4).' },
      { id: 'F7Q12', topic: 'AF', q: 'Identify the missing words. Pragmatism means making decisions that adapt to [ ? ] rather than following rigid rules or procedures.', options: ['the original signed specification', 'real-life situations', 'the estimator\'s first figure', 'a sequential phase-gate only'], correct: 'real-life situations', explain: 'Pragmatism adapts to real life; common sense avoids unnecessary complexity (4.1).' },
      { id: 'F7Q13', topic: 'AF', q: 'Beneath the AgilePM framework sit four named foundational elements. Which listed item is not one of those four?', options: ['Process', 'Planning Poker as a mandatory practice', 'People', 'Project Artifacts'], correct: 'Planning Poker as a mandatory practice', explain: 'The four elements are Process, People, Project Artifacts and Practices. Planning Poker is optional technique guidance (4.1).' },
      { id: 'F7Q14', topic: 'AF', q: 'Consider the following statements about \'Never Compromise Quality\'.\n1. Expected quality should be defined at the beginning of the project\n2. A fit-for-purpose solution is \'good enough\' to meet business needs — not exceeding or falling short', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Quality is fixed early via the DoD; \'good enough\' means meeting the need, not gold-plating (4.3).' },
      { id: 'F7Q15', topic: 'AF', q: 'Under \'Demonstrate Control\', why does a partially completed feature have less business value than a feature not started?', options: ['Because the Definition of Done forbids starting a second story', 'Because incomplete work adds complications without adding usable value', 'Because Parkinson\'s Law applies only to unfinished tasks', 'Because Could Haves must be started before Must Haves'], correct: 'Because incomplete work adds complications without adding usable value', explain: 'Progress is tracked on working solutions; half-done work complicates delivery without adding value (4.3).' },
      { id: 'F7Q16', topic: 'AF', q: 'Which class of work does AgilePM say it can govern that team-level Scrum alone struggles to handle?', options: ['A single-team Sprint Goal', 'Business-related work not directly linked to product development, such as business process change', 'The Daily Scrum', 'The Definition of Done for one product'], correct: 'Business-related work not directly linked to product development, such as business process change', explain: 'AgilePM adds project lifecycle, governance and non-product business change around Scrum (4.4).' },
      { id: 'F7Q17', topic: 'IN', q: 'Which of the following is the exact wording of an Agile leadership principle?', options: ['Leaders are dedicated to protecting the original Gantt chart', 'Leaders are dedicated to learning and growth', 'Leaders are dedicated to individual heroics over team outcomes', 'Leaders are dedicated to replacing autonomy with approval chains'], correct: 'Leaders are dedicated to learning and growth', explain: 'Exact principle: \'Leaders are dedicated to learning and growth\' (5.1).' },
      { id: 'F7Q18', topic: 'IN', q: 'Which of the following reproduce the exact wording of Agile Leadership principles?\n1. Leaders are stewards of organisational values\n2. Leaders enable agility to maximise value and impact\n3. Leadership lives everywhere in the organisation\n4. Leaders ensure every estimate is a single figure before Feasibility ends', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Single-figure estimates before Feasibility are contrary to AgilePM estimating guidance; the other three are exact principles (5.1).' },
      { id: 'F7Q19', topic: 'IN', q: 'Identify the missing words. \'First ask the team\' means defaulting to the team for solutions because they have [ ? ], even with difficult problems.', options: ['the project budget', 'knowledge and context', 'the Solution Backlog', 'formal disciplinary authority'], correct: 'knowledge and context', explain: 'Watts: ask the team first — they have knowledge and context; jumping in with answers undermines them (5.3.6).' },
      { id: 'F7Q20', topic: 'IN', q: 'Consider the following statements about scaled support of Delivery Teams.\n1. An experienced Product Owner may support up to three teams if they share a single Product Backlog\n2. A Scrum Master may effectively support up to three teams', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both PO and SM guidance allows support of up to three teams in the right conditions (5.4).' },
      { id: 'F7Q21', topic: 'IN', q: 'During Feasibility a specialist gives technical input on design and later joins a Delivery Team as a Developer. Which Advisor role were they fulfilling?', options: ['Process Advisor', 'Solution Advisor', 'Business Advisor', 'Business Sponsor'], correct: 'Solution Advisor', explain: 'Solution Advisors collaborate with solution-delivery roles and may later become Developers (5.4).' },
      { id: 'F7Q22', topic: 'IN', q: 'Which of the following are true of Business Analysts in AgilePM?\n1. Business analysis bridges strategy, business needs and an effective business solution\n2. Like Scrum, AgilePM may recognise a Business Analyst as a Developer in some contexts\n3. The Business Analyst always replaces the Product Owner\n4. Business Analysts may influence any or all aspects of a project rather than a single narrow area', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'A BA may support backlog management as a Developer; they do not automatically replace the PO (5.4).' },
      { id: 'F7Q23', topic: 'IN', q: 'Which exact principle is shown when a leader creates conditions for skill, confidence and knowledge so people can act with autonomy?', options: ['Leaders replace mastery with detailed task lists issued daily', 'Leaders embrace and enable team and individual mastery', 'Leaders restrict mastery to the Project Manager', 'Leaders treat mastery as optional if the contract is fixed-price'], correct: 'Leaders embrace and enable team and individual mastery', explain: 'Exact wording: leaders embrace and enable team and individual mastery (5.1).' },
      { id: 'F7Q24', topic: 'CC', q: 'Identify the missing words. Manifesto Principle 6 states that the most efficient and effective method of conveying information to and within any team is [ ? ].', options: ['a comprehensive status report', 'face-to-face conversation', 'an emailed RACI matrix', 'a recorded lecture'], correct: 'face-to-face conversation', explain: 'Principle 6: face-to-face conversation is the most efficient and effective method (2.1.4 / 6.3).' },
      { id: 'F7Q25', topic: 'CC', q: 'Using the Power/Interest Grid, what treatment is recommended for a stakeholder who has high power but little interest?', options: ['Closely engage', 'Keep satisfied', 'Keep informed', 'Monitor with minimum effort'], correct: 'Keep satisfied', explain: 'High power / low interest = keep satisfied (Fig. 6.2).' },
      { id: 'F7Q26', topic: 'CC', q: 'Which of the following are correct treatments on the Power/Interest Grid?\n1. High power, low interest — ignore until they complain\n2. High power, high interest — closely engage\n3. Low power, low interest — monitor (minimum effort)\n4. Low power, high interest — keep informed', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'High power / low interest is keep satisfied, not ignore (Fig. 6.2).' },
      { id: 'F7Q27', topic: 'CC', q: 'Consider the following statements about email as a communication choice.\n1. Many people default to email, but it is best used to confirm previous discussions rather than as the primary method\n2. Emails should be clear and concise with meaningful subject lines', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Email confirms prior discussion and broadcasts information; it is not the primary collaborative method (6.3).' },
      { id: 'F7Q28', topic: 'PR', q: 'What is a Solution Increment, as distinct from a Product Increment?', options: ['The output of a single Developer\'s task board', 'Any change to the Product Backlog during refinement', 'A stepwise refinement of the overall Solution meeting the agreed DoD, which may combine products with training, communications and business change', 'The Terms of Reference produced in Pre-Project'], correct: 'A stepwise refinement of the overall Solution meeting the agreed DoD, which may combine products with training, communications and business change', explain: 'Product Increments come from Delivery Teams; a Solution Increment is the broader outcome, often plus non-product work (7.1).' },
      { id: 'F7Q29', topic: 'PR', q: 'Which of the following are purposes of revisiting Foundations between Project Increments?\n1. Confirm the project is still viable using actual progress and an updated Business Case\n2. Freeze every remaining requirement as a Must Have so contingency can be removed\n3. Refine high-level requirements for the next increment into more actionable work\n4. Update the Delivery Plan from lessons learned', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Do not inflate Must Have effort when new work appears; revisit Foundations to re-validate viability, requirements and the plan (7.4 / 10.2.3.11).' },
      { id: 'F7Q30', topic: 'PR', q: 'Identify the missing words. AgilePM\'s lifecycle guidance is to produce \'just enough detail, [ ? ]\', deferring the rest to the last responsible moment.', options: ['just in case', 'just for audit', 'just in time', 'just for the contract'], correct: 'just in time', explain: 'Just enough detail, just in time — defer to the last responsible moment (7.4).' },
      { id: 'F7Q31', topic: 'PR', q: 'Consider the following statements about the Pre-Project Phase.\n1. It focuses on whether and when to conduct Feasibility, including an early look at the business case and potential benefits\n2. Fine-grained User Stories ready for development must be baselined before Feasibility starts', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Pre-Project is a go/investigate decision. Fine-grained stories belong in Delivery refinement, not Pre-Project (7.2 / 8.2.4).' },
      { id: 'F7Q32', topic: 'PR', q: 'What should each Sprint in the Delivery Phase aim to deliver?', options: ['A horizontal layer of technology only', 'A completed UAT script with no working software', 'A usable Product Increment — ideally a vertical slice that can actually be used', 'The entire Solution Increment on day one'], correct: 'A usable Product Increment — ideally a vertical slice that can actually be used', explain: 'Horizontal layers delay usable value and invite integration problems (7.5).' },
      { id: 'F7Q33', topic: 'ES', q: 'Which of the following are true of the three Cs of a User Story?\n1. Card — the physical or digital card the story is written on\n2. Conversation — discussions that clarify the details\n3. Confirmation — a set of Acceptance Criteria\n4. Contract — a legally binding specification that replaces conversation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The three Cs are Card, Conversation and Confirmation. Contract is not one of them (8.2.3.3).' },
      { id: 'F7Q34', topic: 'ES', q: 'When should Must Have effort typically be reduced below the usual level?', options: ['Whenever the Business Sponsor wants a shorter meeting', 'After every Daily Scrum as a standing rule', 'Only during the Realisation Phase', 'On high-risk work such as new technology or an inexperienced team'], correct: 'On high-risk work such as new technology or an inexperienced team', explain: 'The 60% guide is reduced further when risk is high so more contingency remains (9.5).' },
      { id: 'F7Q35', topic: 'ES', q: 'Identify the missing word. When estimates move, AgilePM still prefers fewer higher-value outcomes over [ ? ] more things in a substandard way.', options: ['documenting', 'estimating', 'workshopping', 'outputting'], correct: 'outputting', explain: 'Adjusted estimates guide what can be achieved; quality, time and cost stay fixed (8.3.2).' },
      { id: 'F7Q36', topic: 'ES', q: 'Consider the following statements about velocity.\n1. Velocity is unique to each team and cannot be compared across teams\n2. It is a measure of output, not outcomes, and should not be the sole measure of delivery progress', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Velocity forecasts capacity; it is not an outcome KPI and is not comparable between teams (8.3.3.2).' },
      { id: 'F7Q37', topic: 'ES', q: 'Who is responsible for estimating the size of Product Backlog items?', options: ['The Business Sponsor, so the figure can be used in the investment board pack', 'The Project Manager, so the Delivery Plan can be issued as a mandate', 'The Process Advisor, because estimating is a facilitation technique', 'The Developers; the Product Owner can guide with business understanding, priorities and trade-offs'], correct: 'The Developers; the Product Owner can guide with business understanding, priorities and trade-offs', explain: 'Those doing the work estimate it; the PO informs, the PM must not influence the numbers (App. A / 8.3).' },
      { id: 'F7Q38', topic: 'ES', q: 'Which of the following are true of Could Have requirements?\n1. They are guaranteed if they appear on the Solution Backlog\n2. They act as a buffer providing the main pool of contingency\n3. They are the first features dropped if the deadline is at risk\n4. AgilePM suggests allocating about 20% of total effort to them', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Could Haves are desirable but not guaranteed; ~20% effort is the typical contingency pool (9.2.3).' },
      { id: 'F7Q39', topic: 'PC', q: 'In Project Sprint Planning Topic 2, who pulls the Product Backlog items they forecast they can get Done?', options: ['The Business Sponsor', 'The Project Manager alone', 'The Process Advisor', 'The Developers in the Delivery Team(s)'], correct: 'The Developers in the Delivery Team(s)', explain: 'Developers pull what they forecast they can get Done; Scrum Masters typically facilitate the split between teams (10.2.3.4).' },
      { id: 'F7Q40', topic: 'PC', q: 'Identify the missing words. An exception arises if the Delivery Team determines that the [ ? ] is at risk — for example if agreed Must Haves will not be delivered.', options: ['email distribution list', 'coffee-card estimate', 'Workshop Facilitator\'s diary', 'Sprint Goal'], correct: 'Sprint Goal', explain: 'Not achieving the Sprint Goal is a major deviation and must be escalated (10.4.2).' },
      { id: 'F7Q41', topic: 'PC', q: 'Which of the following are AgilePM planning concepts?\n1. Outcome-based planning\n2. Planning to sensible horizons\n3. Using burn-down charts to rank Delivery Teams\n4. Plan and re-plan using the most up-to-date estimates', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three planning concepts do not include judging teams by charts — that misuse is explicitly forbidden (10.1 / 10.2).' },
      { id: 'F7Q42', topic: 'PC', q: 'Consider the following statements about continuous delivery during a Sprint.\n1. Deployments of Done Product Increments may be acceptable during a Sprint if they align with the Delivery Plan and do not harm other teams\n2. Such deployments should be planned in Sprint Planning, not performed unilaterally', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Continuous deployment is allowed when planned and non-disruptive; CTR looks ahead to future deployments (10.2.3.6.3).' },
      { id: 'F7Q43', topic: 'PC', q: 'Who typically facilitates the Project Sprint Review, working with co-facilitators?', options: ['The Business Sponsor, with auditors as co-facilitators', 'The Process Advisor only, because Project Roles must stay silent', 'The Developers exclusively, with no Project Role present', 'The Project Manager, working with Scrum Masters and Product Owners as co-facilitators'], correct: 'The Project Manager, working with Scrum Masters and Product Owners as co-facilitators', explain: 'The PM may facilitate overall; SMs and POs co-facilitate. Wider stakeholders and other Project Roles are invited (10.2.3.7).' },
      { id: 'F7Q44', topic: 'RK', q: 'Which of the following are types of constraint called out under PAQ Statement 17?\n1. Internal standards\n2. The Fibonacci sequence used on Planning Poker cards\n3. External (regulatory) standards\n4. Commercial arrangements', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Statement 17 concerns internal, external/regulatory and commercial constraints — not estimating-card sequences (11.2.2.17).' },
      { id: 'F7Q45', topic: 'RK', q: 'Consider the following statements about when a separate formal risk process is needed.\n1. Because agility is designed to handle VUCA day to day, a separate formal risk process is not usually needed\n2. Highly regulated or safety-related contexts are the typical exception where intentional risk processes should be considered in the MAD, SAD and DAD', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Risk is integrated into daily AgilePM; extra formal process is the regulated/safety exception (11.1 / 11.3).' },
      { id: 'F7Q46', topic: 'RK', q: 'If the PAQ shows the project lacks a clear vision, what is the suggested first remedy?', options: ['Cancel every Sprint until a contract variation is signed', 'Replace the Business Visionary with the Scrum Master', 'Convert all Should Haves into Must Haves', 'Ask the Business Visionary to explain the vision clearly and hold a session so teams and stakeholders can question it'], correct: 'Ask the Business Visionary to explain the vision clearly and hold a session so teams and stakeholders can question it', explain: 'PAQ Statement 3: the BV must communicate the vision so every decision can be tested against it (11.2.2.3).' },
      { id: 'F7Q47', topic: 'GV', q: 'Identify the missing word. When creating governance for an agile project, it is important to focus on the [ ? ] behind the governance, then design processes that support that purpose without limiting agility.', options: ['template', 'job title', 'page count', 'purpose'], correct: 'purpose', explain: 'Governance and empiricism need not conflict if you design for the purpose, not the ritual (12.1).' },
      { id: 'F7Q48', topic: 'GV', q: 'Which of the following are true of the Cone (Core) of Uncertainty?\n1. Early estimates are inherently vague and should be given as ranges\n2. Estimate accuracy should improve as the lifecycle progresses\n3. Barry Boehm\'s diagram is the source AgilePM cites\n4. After Pre-Project, a single figure chosen by the estimator is mandatory', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Ranges, not single figures; if a single figure is insisted upon, the Sponsor chooses it — not the estimator (12.3.1).' },
      { id: 'F7Q49', topic: 'GV', q: 'Consider the following statements about RACI for the Product Backlog.\n1. Responsible is the Product Owner; Accountable is the Business Visionary\n2. Responsible is the Developers; Accountable is the Scrum Master', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Product Backlog: R = Product Owner, A = Business Visionary (App. A).' },
      { id: 'F7Q50', topic: 'GV', q: 'What is the basic test of Solution quality, and what further questions does AgilePM still ask?', options: ['Whether the Gantt chart is green; no further questions are required', 'Whether every Could Have was delivered; process quality is ignored', 'Whether the PAQ scored Strongly Agree on every line', 'Whether it meets the business need — plus whether it is technically strong and can handle needs over time without failing'], correct: 'Whether it meets the business need — plus whether it is technically strong and can handle needs over time without failing', explain: 'Meeting the need is the basic test; technical strength and longevity still matter (12.2).' },
    ],
  },
  {
    id: 'final8',
    title: 'Final Paper 8',
    questions: [
      { id: 'F8Q1', topic: 'KC', q: 'What does the Agile Business Consortium\'s enhancement of the Manifesto change, and why?', options: ['It replaces \'software\' with \'solutions\' so value-creation applies beyond software development', 'It removes \'working solutions\' so documentation can be maximised', 'It reverses the fourth value so plans outrank change', 'It deletes the final sentence so items on the right have no value'], correct: 'It replaces \'software\' with \'solutions\' so value-creation applies beyond software development', explain: 'The ABC wording broadens the Manifesto from software to solutions (2.1.3).' },
      { id: 'F8Q2', topic: 'KC', q: 'Identify the missing name. Rapid Application Development was introduced by [ ? ] in 1991.', options: ['James Martin', 'Ken Schwaber', 'Jeff Sutherland', 'Mike Cohn'], correct: 'James Martin', explain: 'RAD (James Martin, 1991) favoured speed; DSDM later restored control and quality (Ch.1).' },
      { id: 'F8Q3', topic: 'KC', q: 'Which of the following are true of empowerment?\n1. Empowerment means there are never any limits on individual authority\n2. Empowerment requires people to be capable, willing and informed\n3. Boundaries of empowerment describe how much freedom someone has to act without extra approval\n4. Leaders keep control of strategic direction while teams manage day-to-day work', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Empowerment is bounded: capable, willing, informed people act within agreed limits (2.1.3).' },
      { id: 'F8Q4', topic: 'KC', q: 'Consider the following statements about Scrum\'s suitability.\n1. Scrum works best where work is complex, the solution is not fully known, and an iterative collaborative approach fits\n2. Scrum is less suited to standardised, highly repetitive work such as routine manufacturing or distribution', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Scrum suits complex product work; it is a poor fit for already well-defined repetitive tasks (2.2).' },
      { id: 'F8Q5', topic: 'KC', q: 'What does the Manifesto\'s final sentence insist we still remember about the items on the right?', options: ['They are useful only when they add real value and include just enough detail', 'They have no value and should be deleted from every project', 'They always outrank the items on the left in a regulated industry', 'They must be signed before any increment can be used'], correct: 'They are useful only when they add real value and include just enough detail', explain: '\'While there is value in the items on the right, we value the items on the left more\' (2.1.3.5).' },
      { id: 'F8Q6', topic: 'SC', q: 'Which of the following are Scrum Values?\n1. Commitment\n2. Focus\n3. Openness\n4. Consensus', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The five values are Commitment, Focus, Openness, Respect and Courage — not Consensus (3.3).' },
      { id: 'F8Q7', topic: 'SC', q: 'Which three elements together make up the Sprint Backlog?', options: ['The Sprint Goal (why), the selected Product Backlog items (what), and an actionable plan for delivering the Increment (how)', 'The Product Goal, the Solution Backlog and the Benefits Assessment', 'Only tasks assigned by the Project Manager', 'The PAQ statements rated Disagree'], correct: 'The Sprint Goal (why), the selected Product Backlog items (what), and an actionable plan for delivering the Increment (how)', explain: 'Sprint Backlog = why + what + how (3.6).' },
      { id: 'F8Q8', topic: 'SC', q: 'Identify the missing words. Schwaber and Sutherland describe Scrum as lightweight, simple to understand, and difficult to [ ? ].', options: ['master', 'document', 'timebox', 'facilitate'], correct: 'master', explain: 'Scrum is \'lightweight, simple to understand, and difficult to master\' (3.1).' },
      { id: 'F8Q9', topic: 'SC', q: 'Consider the following statements about cancelling a Sprint.\n1. Any stakeholder with high power on the Power/Interest Grid may cancel the Sprint\n2. Only the Product Owner can cancel a Sprint, and only if the Sprint Goal becomes obsolete', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Cancellation is solely a PO decision, and only for an obsolete Sprint Goal (3.5).' },
      { id: 'F8Q10', topic: 'SC', q: 'Which of the following are true of the Product Increment?\n1. Each Increment is additive to all prior Increments and must be thoroughly verified\n2. An undone item may still be presented at the Sprint Review if the Project Manager agrees\n3. It must be usable to provide value\n4. It is born the moment a Product Backlog item meets the Definition of Done', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Undone work cannot be released or presented at the Review (3.6).' },
      { id: 'F8Q11', topic: 'SC', q: 'What ongoing activity breaks Product Backlog items into smaller, more precise items and adds description, order and size?', options: ['The act of breaking down and further defining PBIs into smaller, more precise items as an ongoing activity', 'A one-off workshop that freezes every story before Foundations ends', 'The Project Manager\'s weekly status report', 'The only event at which the Sprint Goal may be changed by the Business Sponsor'], correct: 'The act of breaking down and further defining PBIs into smaller, more precise items as an ongoing activity', explain: 'Refinement is ongoing and adds description, order and size (3.6).' },
      { id: 'F8Q12', topic: 'AF', q: 'Identify the missing words. Completing the philosophy sentence: best value emerges when projects are aligned to clear goals, deliver frequently and involve the collaboration of [ ? ].', options: ['external auditors only', 'motivated and empowered people', 'a single command-and-control manager', 'fixed-scope contractors with no business contact'], correct: 'motivated and empowered people', explain: 'Philosophy: clear goals, frequent delivery, motivated and empowered people (4.1).' },
      { id: 'F8Q13', topic: 'AF', q: 'AgilePM names five practices that enable the principles. Which of the following is not one of those five?', options: ['Iterative Development', 'Maximising comprehensive documentation as a practice in its own right', 'Timeboxing (including Sprints)', 'MoSCoW Prioritisation'], correct: 'Maximising comprehensive documentation as a practice in its own right', explain: 'The five practices are iterative development, timeboxing, MoSCoW, modelling and facilitated workshops (4.3).' },
      { id: 'F8Q14', topic: 'AF', q: 'Consider the following statements about Principle 2, Deliver on Time.\n1. A delayed Solution Increment can lose its value, especially if it depends on a market window or legal deadline\n2. Artificial deadlines used only as a measure of success or control can harm the project', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'On-time delivery protects value; fake deadlines used only for control are harmful (4.3).' },
      { id: 'F8Q15', topic: 'AF', q: 'Who is responsible for setting the Definition of Done in an AgilePM project?', options: ['The Business Sponsor, because they hold the budget', 'The Solution Architect, who sets it for the various iterations and ensures it is achievable', 'The Project Manager, because they own the Delivery Plan', 'The Process Advisor, because DoD is a facilitation output'], correct: 'The Solution Architect, who sets it for the various iterations and ensures it is achievable', explain: 'The SA sets and monitors the DoD and quality-assurance standards (4.3 / 5.3).' },
      { id: 'F8Q16', topic: 'AF', q: 'What extra decision-making context does AgilePM wrap around the Product Owner role?', options: ['By transferring backlog ordering to the Business Sponsor', 'By providing a business, user and corporate context so product decisions stay aligned with overall business goals', 'By forbidding the Product Owner from talking to Advisors', 'By making the Product Owner accountable for the project budget'], correct: 'By providing a business, user and corporate context so product decisions stay aligned with overall business goals', explain: 'AgilePM wraps Scrum\'s PO with project-level value and governance context (4.4).' },
      { id: 'F8Q17', topic: 'IN', q: 'Which exact leadership principle is demonstrated by protecting and role-modelling the organisation\'s stated values when trade-offs appear?', options: ['Leaders treat values as optional if a deadline slips', 'Leaders are stewards of organisational values', 'Leaders outsource values to the Process Advisor', 'Leaders replace values with a RACI chart'], correct: 'Leaders are stewards of organisational values', explain: 'Exact wording: leaders are stewards of organisational values (5.1).' },
      { id: 'F8Q18', topic: 'IN', q: 'Select the statements that match published Agile Leadership principles word-for-word.\n1. Leaders foster team accountability\n2. Leaders ensure clarity of purpose\n3. Leaders substitute purpose with a detailed specification signed in Pre-Project\n4. Leaders develop new leaders (not followers)', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The first three are exact principles; a Pre-Project specification replacing purpose is not (5.1).' },
      { id: 'F8Q19', topic: 'IN', q: 'Identify the missing words. \'Make yourself redundant\' measures success by [ ? ] — true leadership is shown when the team becomes more autonomous, capable and empowered.', options: ['the number of status reports filed', 'team growth', 'the Sponsor\'s single-figure estimate', 'how often the Scrum Master answers first'], correct: 'team growth', explain: 'Watts: foster understanding, aim to become redundant, and measure success by team growth (5.3.6).' },
      { id: 'F8Q20', topic: 'IN', q: 'Consider the following statements about Advisor domains.\n1. Business Advisors collaborate with value-ownership roles\n2. Process Advisors collaborate with organisation-enablement roles', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Business → value ownership; Solution → solution delivery; Process → organisation enablement (5.4).' },
      { id: 'F8Q21', topic: 'IN', q: 'At operational level, what does AgilePM say a Business Analyst typically defines?', options: ['The project budget on behalf of the Business Sponsor', 'Detailed acceptance criteria (sometimes called a-suite) so products meet requirements and align with the Definition of Done', 'The Solution Architecture without the Solution Architect', 'The PAQ scores without the Project Manager'], correct: 'Detailed acceptance criteria (sometimes called a-suite) so products meet requirements and align with the Definition of Done', explain: 'Strategic BA work is C-suite; operational BA work is detailed acceptance criteria aligned to the DoD (5.4).' },
      { id: 'F8Q22', topic: 'IN', q: 'AgilePM names four Product Owner relationships. Which of the following belong on that list?\n1. Business Sponsor as a fourth named PO relationship instead of Advisors\n2. Business Visionary\n3. Solution Architect\n4. Project Manager', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The fourth relationship is Business and Technical Advisors, not the Business Sponsor (5.2.5).' },
      { id: 'F8Q23', topic: 'IN', q: 'Which exact principle captures creating conditions so agility produces value rather than theatre?', options: ['Leaders enable agility only after every requirement is frozen', 'Leaders enable agility to maximise value and impact', 'Leaders enable agility by removing the Definition of Done', 'Leaders enable agility solely through more status reporting'], correct: 'Leaders enable agility to maximise value and impact', explain: 'Exact wording: leaders enable agility to maximise value and impact (5.1).' },
      { id: 'F8Q24', topic: 'CC', q: 'Identify the missing words. On the Aligned Autonomy Matrix, high alignment combined with high autonomy describes an [ ? ] organisation with a collaborative culture.', options: ['authoritative', 'innovative', 'bureaucratic', 'entrepreneurial'], correct: 'innovative', explain: 'High/high = innovative organisation (collaborative culture) (Fig. 6.1).' },
      { id: 'F8Q25', topic: 'CC', q: 'A mixed-discipline team cannot drop specialist terms. Besides a glossary, what language behaviour does AgilePM still ask for whenever possible?', options: ['Communicate only through the Project Manager', 'Replace conversation with a longer Business Case', 'Use a common, straightforward language', 'Switch entirely to instant messaging'], correct: 'Use a common, straightforward language', explain: 'Prefer plain shared language; keep a glossary when that is not practical (6.3).' },
      { id: 'F8Q26', topic: 'CC', q: 'Which of the following are Aligned Autonomy Matrix combinations?\n1. High alignment, low autonomy — authoritative organisation (authoritarian culture)\n2. High alignment, high autonomy — bureaucratic organisation\n3. Low alignment, high autonomy — entrepreneurial organisation (chaotic culture)\n4. Low alignment, low autonomy — bureaucratic organisation (indifferent culture)', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'High/high is innovative/collaborative, not bureaucratic (Fig. 6.1).' },
      { id: 'F8Q27', topic: 'CC', q: 'Consider the following statements about face-to-face communication.\n1. It is the most effective way to communicate in small or medium groups such as meetings, Scrum events and facilitated workshops\n2. It allows body language and tone of voice, making communication richer and confusion easier to clear immediately', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Face-to-face is richest for small/medium groups; technology can strip tone and body language (6.3).' },
      { id: 'F8Q28', topic: 'PR', q: 'Once a Solution Increment has been put into operational use, what term does AgilePM use for what it becomes or adds to?', options: ['The Sprint Backlog at the end of Sprint Planning', 'The Terms of Reference after Pre-Project', 'What a Solution Increment becomes (or adds to) once it has been deployed into operational use', 'The PAQ after Foundations'], correct: 'What a Solution Increment becomes (or adds to) once it has been deployed into operational use', explain: 'Several Product Increments may form a Solution Increment; deployment produces the Deployed Solution (7.1).' },
      { id: 'F8Q29', topic: 'PR', q: 'Which of the following should the Business Case during Feasibility be?\n1. An outline sufficient to judge likely desirability and viability\n2. Evolutionary, later expanded in Foundations\n3. Focused on purpose and justification rather than a substitute for the Delivery Plan\n4. A fully detailed investment model that never changes after Pre-Project', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The Business Case starts as an outline and evolves; it is not a frozen plan or a replacement Delivery Plan (7.3–7.4).' },
      { id: 'F8Q30', topic: 'PR', q: 'Identify the missing words. Even for large projects, the Foundations Phase should typically last only a [ ? ].', options: ['calendar year', 'single Daily Scrum', 'short number of weeks', 'full Project Increment of 6–12 months'], correct: 'short number of weeks', explain: 'Foundations is a short, timeboxed discovery — weeks, not a drawn-out analysis phase (7.4 / 10.2).' },
      { id: 'F8Q31', topic: 'PR', q: 'Consider the following statements about subsequent passes through Foundations.\n1. They reduce risk by keeping early planning flexible\n2. They avoid unnecessary complexity caused by VUCA', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Revisiting Foundations applies learning and keeps long-term detail until it is needed (7.4).' },
      { id: 'F8Q32', topic: 'PR', q: 'Which milestone artefact combines key findings from Feasibility for a governance go/no-go?', options: ['The Sprint Backlog', 'The Daily Scrum notes', 'The Feasibility Assessment', 'The Benefits Assessment'], correct: 'The Feasibility Assessment', explain: 'The Feasibility Assessment is a milestone snapshot used to decide whether to continue (7.3 / App. A).' },
      { id: 'F8Q33', topic: 'ES', q: 'Which of the following are true of the estimating cycle?\n1. Estimates become more precise as requirements become clearer\n2. Estimates are not fixed — they evolve as information emerges\n3. Delivery-phase estimates must never use actual velocity\n4. Feasibility estimates are rough and based on limited information', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Delivery uses real performance/velocity to refine predictions (8.3.4).' },
      { id: 'F8Q34', topic: 'ES', q: 'Who invented User Story Mapping?', options: ['Dan North', 'James Grenning', 'Barry Boehm', 'Jeff Patton'], correct: 'Jeff Patton', explain: 'Story Mapping is a visual method invented by Jeff Patton (8.2.3).' },
      { id: 'F8Q35', topic: 'ES', q: 'Identify the missing words. A Must Have requirement cannot depend on anything other than a [ ? ], because Shoulds or Coulds might not be delivered.', options: ['Could Have', 'Won\'t Have this time', 'Should Have', 'Must Have'], correct: 'Must Have', explain: 'Dependencies of a Must Have on lower priorities would break the Minimum Usable Subset (9.8).' },
      { id: 'F8Q36', topic: 'ES', q: 'Consider the following statements about Acceptance Criteria and the Definition of Done.\n1. Meeting Acceptance Criteria is a minimum for the requirement and is usually just one box to tick on the DoD\n2. Acceptance Criteria and the DoD are the same artefact and may be used interchangeably', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'AC confirm a story\'s need; DoD is the shared quality bar for the Increment (8.2.3.7).' },
      { id: 'F8Q37', topic: 'ES', q: 'What is a useful technique for assigning MoSCoW priorities?', options: ['Start with everything as a Must Have and negotiate downwards only if the Sponsor insists', 'Let the Project Manager assign priorities without the Business Visionary', 'Prioritise after the increment has already finished', 'Start with all requirements as Won\'t Haves and promote them only with strong justification'], correct: 'Start with all requirements as Won\'t Haves and promote them only with strong justification', explain: 'Starting at Won\'t Have prevents everything becoming a Must Have (9.8.1).' },
      { id: 'F8Q38', topic: 'ES', q: 'Which of the following are four key points to consider when estimating?\n1. Freeze estimates at Feasibility so they can be used as a performance target\n2. Include contingency\n3. Estimate only as precisely as needed for the level of understanding\n4. Involve the people doing the work', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The fourth point is continuously revalidate — not freeze Feasibility figures as targets (8.3.1).' },
      { id: 'F8Q39', topic: 'PC', q: 'What is a Scrum of Scrums primarily used for?', options: ['Replacing the Sprint Retrospective', 'Approving the Business Case', 'Estimating the Product Backlog in hours for the Sponsor', 'Letting representatives share updates and manage cross-team dependencies every few days'], correct: 'Letting representatives share updates and manage cross-team dependencies every few days', explain: 'SoS complements, and does not replace, collaboration as needed (10.2.3.6.2).' },
      { id: 'F8Q40', topic: 'PC', q: 'Identify the missing words. Medium-term planning focuses on the next Project Increment or upcoming series of Sprints, typically aligned to the [ ? ] for that increment.', options: ['coffee-card baseline only', 'PAQ Statement 17 only', 'Cone of Uncertainty outer band', 'Solution Goal and Product Goal'], correct: 'Solution Goal and Product Goal', explain: 'The three horizons are long-term (whole project), medium-term (increment/goals) and short-term (Sprint) (10.2.2.2).' },
      { id: 'F8Q41', topic: 'PC', q: 'Which of the following are the four AgilePM tracking and control concepts?\n1. Outcome-based measurement\n2. Management by Gantt-chart variance only\n3. Transparency of process and progress\n4. Responding to change', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The fourth concept is Management by Exception, not Gantt-only control (10.1).' },
      { id: 'F8Q42', topic: 'PC', q: 'Consider the following statements about unfinished requirements.\n1. They should be reviewed at least at the end of each Sprint and each Project Increment\n2. Once placed on a backlog they are guaranteed for the current increment', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Priorities are inspected continuously; a backlog entry is not a delivery guarantee (10.2.3.11 / 8.2).' },
      { id: 'F8Q43', topic: 'PC', q: 'When issues affect the broader project, to whom must exceptions impacting delivery also be escalated?', options: ['Only the Process Advisor', 'The Workshop Facilitator', 'Any low-power, low-interest stakeholder', 'The Project Manager'], correct: 'The Project Manager', explain: 'Team-level exceptions stay with the team; broader delivery impact goes to the PM, who then involves PO/BV and other roles (10.4.2).' },
      { id: 'F8Q44', topic: 'RK', q: 'Which of the following are true of the PAQ?\n1. It contains 17 statements rated on a consensus scale from Strongly Agree to Strongly Disagree\n2. It is typically first used in Feasibility and reviewed again at the end of Foundations\n3. If any statement is considered not true, it indicates a risk to using AgilePM successfully\n4. Completing it once in Pre-Project means it must never be looked at again', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The PAQ is reviewed whenever Foundations is revisited so tailoring stays valid (11.2.1).' },
      { id: 'F8Q45', topic: 'RK', q: 'Consider the following statements about PAQ Statement 10 (empowerment).\n1. A framework of empowerment underpins both AgilePM and Scrum\n2. Agile methods are compatible with a strict top-down style that requires Project Role approval for every day-to-day decision', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'If the organisation will not empower teams, it cannot fully adopt AgilePM (11.2.2.10).' },
      { id: 'F8Q46', topic: 'RK', q: 'If the Delivery Team lacks technical skills (PAQ Statement 12), which option is consistent with AgilePM\'s suggested actions?', options: ['Ignore the gap and increase Must Have effort above 80%', 'Extend the Sprint to six months so a single specialist can finish alone', 'Transfer estimating to the Business Sponsor', 'Work with the available team and train them, or bring in a specialist, keeping any one-person task manageable inside a Sprint'], correct: 'Work with the available team and train them, or bring in a specialist, keeping any one-person task manageable inside a Sprint', explain: 'Train, hire, or split work; do not hide a 10-day task inside a 10-day Sprint (11.2.2.12).' },
      { id: 'F8Q47', topic: 'GV', q: 'Identify the missing words. Traditional compliance-heavy governance is sometimes described as the Manifesto \'[ ? ]\'.', options: ['in full', 'without values', 'for contractors only', 'in reverse'], correct: 'in reverse', explain: 'Processes over people, documents over working solutions, contracts over collaboration, plan over change (12.1.1).' },
      { id: 'F8Q48', topic: 'GV', q: 'Which RACI pairings are correct?\n1. Terms of Reference — Responsible Business Visionary, Accountable Business Sponsor\n2. Solution Architecture Definition — Responsible Solution Architect, Accountable Business Visionary\n3. Product Increment — Responsible Business Sponsor, Accountable Scrum Master\n4. Delivery Approach Definition — Responsible Solution Architect, Accountable Project Manager', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Product Increment: R = Delivery Team, A = Product Owner (App. A).' },
      { id: 'F8Q49', topic: 'GV', q: 'Consider the following statements about two kinds of quality.\n1. Solution quality is how well the delivered Solution meets the organisation\'s needs\n2. Process quality is whether the work to build the Solution was done in a controlled, disciplined — and where required, auditable — way', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Never Compromise Quality covers both the outcome and the way it was built (12.2).' },
      { id: 'F8Q50', topic: 'GV', q: 'Who is Responsible and who is Accountable for the Solution Increment?', options: ['Responsible: Product Owner; Accountable: Scrum Master', 'Responsible: Business Sponsor; Accountable: Developers', 'Responsible: Process Advisor; Accountable: Project Manager', 'Responsible: Project Organisation; Accountable: Business Visionary'], correct: 'Responsible: Project Organisation; Accountable: Business Visionary', explain: 'Solution Increment RACI: R = Project Organisation, A = Business Visionary (App. A).' },
    ],
  },
  {
    id: 'final9',
    title: 'Final Paper 9',
    questions: [
      { id: 'F9Q1', topic: 'KC', q: 'How is Business Agility achieved, according to the Agile Business Consortium?', options: ['By inspiring, enabling and harnessing the collaborative and creative ways of working in an organisation\'s people to meet its core purpose', 'By enforcing Scientific Management so staff operate systems without questioning the rules', 'By fixing features and allowing time and cost to expand without limit', 'By measuring progress only as percentage complete against a baseline'], correct: 'By inspiring, enabling and harnessing the collaborative and creative ways of working in an organisation\'s people to meet its core purpose', explain: 'Business Agility is people-centric: inspire, enable and harness collaborative, creative working (2.1.1).' },
      { id: 'F9Q2', topic: 'KC', q: 'Identify the missing word. Volatility in VUCA means things change [ ? ] and unpredictably.', options: ['quickly', 'slowly', 'never', 'only after deployment'], correct: 'quickly', explain: 'Volatility is rapid, unpredictable change (2.1.2).' },
      { id: 'F9Q3', topic: 'KC', q: 'Which of the following are advantages of an incremental approach?\n1. The organisation gains value early\n2. Users must wait until the final phase before engaging with any product\n3. The business case becomes stronger as benefits are seen and measured\n4. Parts already in use become more stable and reliable', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Incremental delivery brings early value, a stronger case, stability and real-user engagement (2.4).' },
      { id: 'F9Q4', topic: 'KC', q: 'Consider the following statements about project management versus product development.\n1. Project management is primarily about delivering specific, time-bound outcomes within set parameters\n2. Product management is primarily about continuous value creation for customers and the organisation', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'PM provides structure and oversight for a time-bound outcome; product management is ongoing and customer-driven (2.2–2.3).' },
      { id: 'F9Q5', topic: 'KC', q: 'Who from the AgilePM lineage was a signatory of the Agile Manifesto?', options: ['Arie van Bennekum', 'Frederick Winslow Taylor', 'Barry Boehm', 'Geoff Watts'], correct: 'Arie van Bennekum', explain: 'Arie van Bennekum was a Manifesto signatory and part of the team behind what became AgilePM (2.1.3).' },
      { id: 'F9Q6', topic: 'SC', q: 'Scrum theory rests on three empirical pillars. Which set is correct?\n1. Documentation\n2. Transparency\n3. Inspection\n4. Adaptation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Empiricism is transparency, inspection and adaptation. Documentation is not a pillar (3.2).' },
      { id: 'F9Q7', topic: 'SC', q: 'What is the \'nutshell\' sequence of Scrum?', options: ['A Product Owner orders work on a Product Backlog; the Scrum Team turns a selection into an Increment during a Sprint; the team and stakeholders inspect and adjust; repeat', 'The PM issues a Gantt chart; Developers execute it; a steering group signs off once', 'Feasibility, Foundations and Deployment with no Sprints', 'A Process Advisor estimates; the Sponsor codes; the Scrum Master accepts'], correct: 'A Product Owner orders work on a Product Backlog; the Scrum Team turns a selection into an Increment during a Sprint; the team and stakeholders inspect and adjust; repeat', explain: 'Scrum\'s nutshell is order, sprint, inspect, repeat (3.1).' },
      { id: 'F9Q8', topic: 'SC', q: 'Identify the missing word. Transparency without inspection is misleading and [ ? ].', options: ['wasteful', 'empowering', 'empirical', 'sufficient'], correct: 'wasteful', explain: 'Transparency enables inspection; without inspection it is misleading and wasteful (3.2).' },
      { id: 'F9Q9', topic: 'SC', q: 'Consider the following statements about the Sprint.\n1. Sprints are fixed-length events of one month or less, and a new Sprint starts immediately after the previous one\n2. Quality may decrease during the Sprint if that helps protect the Sprint Goal', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'No changes that endanger the Sprint Goal; quality does not decrease (3.5).' },
      { id: 'F9Q10', topic: 'SC', q: 'Sprint Planning is structured around three questions. Which of the following belong?\n1. Why is this Sprint valuable?\n2. What can be Done this Sprint?\n3. Who should be blamed if yesterday\'s estimate was wrong?\n4. How will the chosen work get done?', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three topics are why, what and how — not blame (3.5).' },
      { id: 'F9Q11', topic: 'SC', q: 'What is \'True Leadership\' as the Scrum Guide now states it for the Scrum Master?', options: ['Success is defined by how many people report to the Scrum Master', 'Success is defined by the effectiveness of their Delivery Team(s), coming from developing others', 'Success is defined by the Scrum Master answering every team question first', 'Success is defined by the Scrum Master owning the Product Backlog'], correct: 'Success is defined by the effectiveness of their Delivery Team(s), coming from developing others', explain: 'True/servant leadership: success is the team\'s effectiveness (5.3.6 / Scrum Guide).' },
      { id: 'F9Q12', topic: 'AF', q: 'Identify the missing word. In a traditional sequential approach, [ ? ] are normally fixed while time and cost vary.', options: ['quality standards only', 'features', 'Daily Scrum attendees', 'PAQ statements'], correct: 'features', explain: 'Sequential: features fixed, time/cost vary (and quality often becomes an accidental variable). AgilePM reverses this (4.2).' },
      { id: 'F9Q13', topic: 'AF', q: 'Which of the following is not among AgilePM\'s eight principles (rules of engagement)?', options: ['Focus on the Business Need', 'Maximise work in progress regardless of the Definition of Done', 'Never Compromise Quality', 'Communicate Continuously and Clearly'], correct: 'Maximise work in progress regardless of the Definition of Done', explain: 'The eight principles do not include maximising WIP without quality; Demonstrate Control is the eighth (4.3).' },
      { id: 'F9Q14', topic: 'AF', q: 'Consider the following statements about Principle 5.\n1. Strong foundations for the solution and ways of working should exist before major development work begins\n2. Early on, teams should gain a high-level understanding of the business problem, the proposed solution and associated risk', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Build Incrementally from Firm Foundations: understand problem, solution and risk at a high level first (4.3).' },
      { id: 'F9Q15', topic: 'AF', q: 'Under Principle 7, documentation should be created only when which conditions apply?', options: ['Whenever a methodology checklist still has an empty box', 'It adds value to organisational or user understanding, helps development and support, or is essential for safety-critical or regulatory compliance', 'Only if the Project Manager has spare time in the Daily Scrum', 'Never — AgilePM forbids all documents'], correct: 'It adds value to organisational or user understanding, helps development and support, or is essential for safety-critical or regulatory compliance', explain: 'Principle 7: create documents only if they add value, aid support, or are required for safety/regulation (4.3).' },
      { id: 'F9Q16', topic: 'AF', q: 'What three things should the Project Manager do to support the Collaborate principle?', options: ['Write the Business Case, order the Product Backlog, and cancel Sprints', 'Ensure the right stakeholders are involved at the right time, encourage active business participation, and ensure the Project Organisation is empowered to decide', 'Replace workshops with email-only approvals', 'Keep Value Ownership roles away from Delivery Teams until Deployment'], correct: 'Ensure the right stakeholders are involved at the right time, encourage active business participation, and ensure the Project Organisation is empowered to decide', explain: 'Principle 3 asks the PM to enable involvement, participation and empowerment — a one-team culture (4.3).' },
      { id: 'F9Q17', topic: 'IN', q: 'Which exact leadership principle is first in the AgilePM account of agile leadership?', options: ['Leadership is reserved for those with budget authority', 'Leadership lives everywhere in the organisation', 'Leadership requires a command-and-control style at all times', 'Leadership is replaced by the Delivery Plan'], correct: 'Leadership lives everywhere in the organisation', explain: 'The first principle is the exact wording \'Leadership lives everywhere in the organisation\' (5.1).' },
      { id: 'F9Q18', topic: 'IN', q: 'According to the nine leadership principles, which wordings are correct?\n1. Leaders favour ecosystems over hierarchies\n2. Leaders embrace and enable team and individual mastery\n3. Leaders are dedicated to learning and growth\n4. Leaders favour hierarchies over ecosystems whenever a deadline is near', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Favouring hierarchies under pressure contradicts \'Leaders favour ecosystems over hierarchies\' (5.1).' },
      { id: 'F9Q19', topic: 'IN', q: 'Identify the missing words. Jumping in with your own answers as Scrum Master can [ ? ] the value of team members.', options: ['increase', 'undermine', 'estimate', 'baseline'], correct: 'undermine', explain: '\'First ask the team\': resist answering first because it undermines members\' value (5.3.6).' },
      { id: 'F9Q20', topic: 'IN', q: 'Consider the following statements about the Business Sponsor.\n1. The role is always fulfilled by a single person, though in complex contexts they may represent a governing group\n2. Financial accountabilities may still be governed by a higher authority such as an investment board', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'One named Sponsor; they may represent a committee, and funding may sit with a higher board (5.3).' },
      { id: 'F9Q21', topic: 'IN', q: 'A Workshop Facilitator who plans, organises and runs workshops without owning the workshop\'s business content is an example of which role?', options: ['Business Sponsor', 'Process Advisor', 'Solution Advisor', 'Product Owner'], correct: 'Process Advisor', explain: 'Process Advisors include Agile Coaches and independent Workshop Facilitators (5.4 / 6.4).' },
      { id: 'F9Q22', topic: 'IN', q: 'Which of the following are true of external stakeholders?\n1. The Scrum Master alone owns all external-stakeholder relationships without the Business Visionary or Solution Architect\n2. They are not directly part of the project organisation but still have influence\n3. They may be internal employees affected by a change, or external customers, suppliers or regulators\n4. Purpose, timing, authority and constraints influence how they interact', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'BV and SA manage those relationships, facilitated by the PM (5.2).' },
      { id: 'F9Q23', topic: 'IN', q: 'At strategic level, who do Business Analysts assist, and on what?', options: ['Developers only, on task-level estimates', 'Executives (C-suite) in defining and shaping business strategies that impact the entire organisation', 'The Process Advisor, on Planning Poker facilitation', 'Auditors, on cancelling Sprints'], correct: 'Executives (C-suite) in defining and shaping business strategies that impact the entire organisation', explain: 'Strategic BA work is C-suite strategy; operational BA work is detailed acceptance criteria (5.4).' },
      { id: 'F9Q24', topic: 'CC', q: 'Identify the missing word. Highsmith reminds us that real understanding, discipline and skill do not come from paperwork or strict rules: \'Documentation is not understanding, [ ? ] is not discipline, formality is not skill.\'', options: ['collaboration', 'process', 'MoSCoW', 'velocity'], correct: 'process', explain: 'The middle clause is \'process is not discipline\' (6.4).' },
      { id: 'F9Q25', topic: 'CC', q: 'If communication styles do not match a person\'s level of power and influence, what does AgilePM warn may be lost?', options: ['The Fibonacci sequence', 'The Definition of Ready', 'Valuable opportunities', 'The Cone of Uncertainty'], correct: 'Valuable opportunities', explain: 'Mismatch of style to power/influence wastes opportunity; mismatch to interest can turn enthusiasts resistant (Fig. 6.2).' },
      { id: 'F9Q26', topic: 'CC', q: 'Which of the following are the four benefits of collaboration listed by AgilePM?\n1. Improve problem-solving\n2. Guarantee that every Could Have is delivered\n3. Improve learning\n4. Increase productivity', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The fourth listed benefit is cross-functional learning, not a delivery guarantee (6.2).' },
      { id: 'F9Q27', topic: 'CC', q: 'Consider the following statements about over-using technology.\n1. Replacing face-to-face discussion with email or messaging can lead to misunderstanding because body language and tone are absent\n2. Virtual meetings can be nearly as effective if video and audio are reliable, though the view of body language is restricted', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Prefer face-to-face; if remote, prefer reliable video over audio-only (6.3).' },
      { id: 'F9Q28', topic: 'PR', q: 'What does the Feasibility Phase examine at a high level?', options: ['Only the colour of the Team Board', 'Fine-grained tasks for every Developer for the next year', 'Solution feasibility, stakeholder desirability and viability, and people\'s capability to work in an agile way', 'The final Benefits Assessment after Realisation'], correct: 'Solution feasibility, stakeholder desirability and viability, and people\'s capability to work in an agile way', explain: 'Feasibility tests whether the project is possible, desirable, viable and capable of being run in an agile way (7.3).' },
      { id: 'F9Q29', topic: 'PR', q: 'Which of the following are focus areas of the Foundations Phase?\n1. A clearer understanding of solution requirements and how they shape the project\n2. Expanding Feasibility\'s high-level requirements — especially those for the first increment — usually into the tens, probably fewer than 100\n3. Completing every fine-grained story to Definition of Done before Delivery starts\n4. Stakeholder needs and technical or operational constraints', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Foundations stays high-level enough to commit; fine detail waits for Delivery (7.4).' },
      { id: 'F9Q30', topic: 'PR', q: 'Identify the missing words. A Product Increment is a stepwise refinement of a Product that meets the agreed [ ? ] and is ideally usable right away.', options: ['contract schedule', 'PAQ Statement 1', 'Definition of Done', 'investment-board minute'], correct: 'Definition of Done', explain: 'Both Product and Solution Increments are additive refinements that meet the agreed DoD (7.1).' },
      { id: 'F9Q31', topic: 'PR', q: 'Consider the following statements about the Delivery Plan at the end of Foundations.\n1. It should include a high-level schedule of Sprints for the next (or only) Project Increment, often with speculative Sprint Goals\n2. The team should be confident to commit to delivery dates and costs for the upcoming Delivery Phase', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Foundations produces a commit-able plan for the next increment, not a detailed task list for every later increment (7.4 / 10.2).' },
      { id: 'F9Q32', topic: 'PR', q: 'Who is responsible for embedding the solution during Realisation, and who is accountable for RoI?', options: ['Scrum Master embeds; Developers are accountable for RoI', 'Process Advisor embeds; Product Owner is accountable for RoI', 'Business Visionary embeds; Business Sponsor is accountable for RoI', 'Project Manager embeds and is solely accountable for RoI'], correct: 'Business Visionary embeds; Business Sponsor is accountable for RoI', explain: 'BV embeds so benefits happen; BS remains accountable for return on investment (7.7).' },
      { id: 'F9Q33', topic: 'ES', q: 'Which of the following correctly describe levels of User Story detail?\n1. Epic stories — the only format permitted during Sprint Planning Topic 3\n2. Epic stories — Feasibility, broad enough to scope the solution\n3. User Stories — typically refined in Foundations, still relatively high-level\n4. Fine-grained User Stories — ready for a Sprint during Delivery', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Topic 3 works with ready, fine-grained items, not Feasibility epics (8.2.3 / 8.2.4).' },
      { id: 'F9Q34', topic: 'ES', q: 'What does INVEST\'s \'Negotiable\' criterion mean?', options: ['The story is a signed contract that cannot be discussed', 'The story must be estimated by the Business Sponsor', 'The story cannot be split', 'The story is flexible and open to discussion'], correct: 'The story is flexible and open to discussion', explain: 'Negotiable = open to conversation, not a frozen specification (8.2.3.4).' },
      { id: 'F9Q35', topic: 'ES', q: 'Identify the missing words. T-shirt estimating categorises items into sizes such as Small, Medium, Large and [ ? ].', options: ['Must Have', 'Done', 'Could Have', 'Extra Large'], correct: 'Extra Large', explain: 'T-shirt sizes (S/M/L/XL) are a fast analogy technique for early estimates (8.3.3).' },
      { id: 'F9Q36', topic: 'ES', q: 'Consider the following statements about MoSCoW and timeframes.\n1. A requirement\'s priority at Project Increment level may differ from its priority at whole-project level\n2. MoSCoW mandates the exact order in which requirements must be built', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'MoSCoW describes importance, not build sequence; dependencies and efficiency still shape order (9.3–9.4).' },
      { id: 'F9Q37', topic: 'ES', q: 'Who created Planning Poker (first described in 2002), and who later popularised it?', options: ['Barry Boehm created it; Frederick Taylor popularised it', 'Ken Schwaber created it; the Business Sponsor popularised it', 'Rachel Davies created it; Jeff Patton popularised it', 'James Grenning created it; Mike Cohn popularised it in Agile Estimating and Planning'], correct: 'James Grenning created it; Mike Cohn popularised it in Agile Estimating and Planning', explain: 'Grenning 2002; Cohn popularised it. Both were Manifesto contributors (App. C).' },
      { id: 'F9Q38', topic: 'ES', q: 'Which of the following are true of Planning Poker?\n1. Cards stay hidden until revealed so early opinions do not sway others\n2. The Project Manager observes to understand assumptions but does not estimate or influence the team\n3. If estimates are close (e.g. 3s and 5s), the higher card value is taken\n4. The Business Sponsor must play a card for every story', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Developers estimate; the PM must not influence; the Sponsor does not play cards (App. C).' },
      { id: 'F9Q39', topic: 'PC', q: 'How does AgilePM define outcome-based measurement as a control concept?', options: ['Tracking progress by tasks completed on a checklist regardless of use', 'Comparing team velocities to rank Delivery Teams', 'Counting the number of pages in the Management Approach Definition', 'Tracking progress based on delivered value, remembering that outcome is realised when the product or solution is used in operation'], correct: 'Tracking progress based on delivered value, remembering that outcome is realised when the product or solution is used in operation', explain: 'An Increment is an output; the outcome appears in operational use (10.4.1).' },
      { id: 'F9Q40', topic: 'PC', q: 'Identify the missing words. The most common Sprint length for consistency across teams is [ ? ].', options: ['six months', 'one day', 'the entire Project Increment', 'two weeks'], correct: 'two weeks', explain: 'Two weeks is most common; 1–4 weeks is normal; six weeks is the maximum recommended (10.2.3.3).' },
      { id: 'F9Q41', topic: 'PC', q: 'Cross-Team Refinement is lightly prescribed. Which of the following match the book\'s recommended pattern?\n1. Project Roles and Product Owner(s), plus all or representatives of the Scrum Teams\n2. The Business Sponsor as the only permitted attendee\n3. Typical Scrum artefacts plus Project Artefacts such as the Business Case, goals, backlogs and Delivery Plan\n4. Frequency of at least once every Sprint', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'CTR is for Project Roles, POs and team representatives — not a Sponsor-only meeting (10.2.3.6.1).' },
      { id: 'F9Q42', topic: 'PC', q: 'Consider the following statements about the spirit of the Project Sprint Review.\n1. It is a joint review with Delivery Teams represented, to inspect the Sprint and collaborate on what to do next\n2. It should be the Delivery Teams reporting to management to be grilled on whether they met the Sprint Goal', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Same spirit as a Scrum Review: inspect and adapt, not a management grilling (10.2.3.7).' },
      { id: 'F9Q43', topic: 'PC', q: 'What should deployment planning reserve so the team can restore the previous technical and business system if major problems arise?', options: ['A longer Sprint with no DoD', 'A single-figure estimate chosen by the estimator', 'A Won\'t Have list that is discarded rather than documented', 'A rollback option, and a Plan B if rollback is not possible'], correct: 'A rollback option, and a Plan B if rollback is not possible', explain: 'Plan resources, business-change activities, rollback, and a Plan B (10.2.3.9).' },
      { id: 'F9Q44', topic: 'RK', q: 'Which of the following are ways AgilePM handles VUCA-related risk in normal operation?\n1. Using philosophy, principles and practices to guide value delivery\n2. Holding workshops in Feasibility and Foundations to address risks early\n3. Requiring a separate enterprise risk register before any Daily Scrum\n4. Continuously reviewing risk as part of backlog refinement', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Separate formal risk process is the regulated/safety exception, not a Daily Scrum prerequisite (11.1).' },
      { id: 'F9Q45', topic: 'RK', q: 'Consider the following statements about PAQ Statement 5.\n1. Participants must accept that requirements can be prioritised and that time and cost commitments are met by flexing scope\n2. Even a high-level Must Have can reveal Should/Could flexibility when it is broken down (for example, make appointment vs change appointment)', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Scope is the contingency; decomposition often exposes lower-priority slices inside a Must Have (11.2.2.5).' },
      { id: 'F9Q46', topic: 'RK', q: 'What does PAQ Statement 16 say is the primary way to measure project progress?', options: ['Hours booked to a cost code', 'The number of pages added to the Business Case', 'Attendance at the Daily Scrum', 'The incremental delivery of demonstrable value'], correct: 'The incremental delivery of demonstrable value', explain: 'Progress is tangible increments stakeholders can see and use (11.2.2.16).' },
      { id: 'F9Q47', topic: 'GV', q: 'Identify the missing words. Only after the [ ? ] can Delivery Teams give more solid estimates; before that, estimates are rough indicators.', options: ['Pre-Project Phase', 'Realisation Phase', 'first Daily Scrum', 'Foundations Phase'], correct: 'Foundations Phase', explain: 'Solid estimates wait until Foundations understanding exists (12.3.1).' },
      { id: 'F9Q48', topic: 'GV', q: 'Which of the following are Project Artefacts relevant to financial governance?\n1. The Business Case\n2. The Feasibility Assessment\n3. The Foundations Summary\n4. The Daily Scrum', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Financial-governance artefacts include Feasibility Assessment, Business Case, Foundations Summary, Project Review Report and Benefits Assessment (12.3.2).' },
      { id: 'F9Q49', topic: 'GV', q: 'Consider the following statements about RACI for the Sprint Backlog.\n1. Responsible is the Developers; Accountable is the Product Owner\n2. Responsible is the Project Manager; Accountable is the Business Sponsor', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Sprint Backlog: R = Developers, A = Product Owner (App. A).' },
      { id: 'F9Q50', topic: 'GV', q: 'What must a responsible organisation still do about investment decisions in an agile environment?', options: ['Avoid all cost and benefit questions because they conflict with agility', 'Force the estimator to pick a single figure in Pre-Project', 'Treat the first Feasibility range as a contractual penalty clause', 'Know projected cost and impact, understand expected return, and judge whether the project or next stage is worth pursuing'], correct: 'Know projected cost and impact, understand expected return, and judge whether the project or next stage is worth pursuing', explain: 'Financial governance is still required; AgilePM answers it with ranges, MoSCoW and timeboxes (12.3).' },
    ],
  },
  {
    id: 'final10',
    title: 'Final Paper 10',
    questions: [
      { id: 'F10Q1', topic: 'KC', q: 'In which month, year and place did seventeen software experts produce the Agile Manifesto?', options: ['February 2001, Snowbird, Utah, USA, by 17 software development experts', '1994, London, by the DSDM Consortium board', '2010, by the Agile Business Consortium at its rebrand', '1991, by James Martin as part of RAD'], correct: 'February 2001, Snowbird, Utah, USA, by 17 software development experts', explain: 'Seventeen experts at Snowbird in February 2001 authored the Manifesto (2.1.3).' },
      { id: 'F10Q2', topic: 'KC', q: 'Identify the missing word. Uncertainty in VUCA means it is hard to know what will happen or to make accurate [ ? ].', options: ['predictions', 'timeboxes', 'RACI charts', 'user personas'], correct: 'predictions', explain: 'Uncertainty is the difficulty of knowing what will happen or predicting accurately (2.1.2).' },
      { id: 'F10Q3', topic: 'KC', q: 'Which of the following are true of agile contracts as described by AgilePM?\n1. They should be co-created by those who will use them\n2. They should focus on success rather than assigning blame\n3. They should assume nothing will change, as traditional fixed-scope contracts do\n4. They should not focus on enforcing a rigid, unchanging scope', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Traditional fixed-scope contracts assume no change; agile contracts must allow flexibility (2.1.3).' },
      { id: 'F10Q4', topic: 'KC', q: 'Consider the following statements about why agility is still valuable in relatively stable projects.\n1. It still improves communication and increases stakeholder involvement\n2. It still supports better results and incremental delivery of benefits at no extra inherent cost or risk from using agility itself', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Even stable work benefits from communication, involvement, results and incremental benefits (2.4.3).' },
      { id: 'F10Q5', topic: 'KC', q: 'What does product development focus on, as distinct from project management?', options: ['What the product is or needs to become, and how it is designed, built and improved over time', 'Who is on the steering group and where they sit', 'The portfolio-level decision to start Feasibility', 'Holding the project budget'], correct: 'What the product is or needs to become, and how it is designed, built and improved over time', explain: 'Product development is the what/how of the evolving product (2.2).' },
      { id: 'F10Q6', topic: 'SC', q: 'Which of the following are true of the Scrum Team?\n1. It consists of one Scrum Master, one Product Owner and Developers\n2. The Project Manager is a fourth required Scrum Team role\n3. There are no sub-teams or hierarchies, and the team focuses on one Product Goal at a time\n4. Typical size is 10 or fewer people', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The PM is an AgilePM project role, not a Scrum Team role (3.4).' },
      { id: 'F10Q7', topic: 'SC', q: 'What does Inspection enable in Scrum, and when is inspection without that next step considered pointless?', options: ['It enables Adaptation; inspection without adaptation is pointless', 'It enables a Gantt baseline; inspection without a baseline is pointless', 'It enables the Sponsor to cancel the Sprint; otherwise inspection is pointless', 'It enables single-figure estimates; otherwise inspection is pointless'], correct: 'It enables Adaptation; inspection without adaptation is pointless', explain: 'Transparency → inspection → adaptation, as soon as possible (3.2).' },
      { id: 'F10Q8', topic: 'SC', q: 'Identify the missing words. The Sprint is described as the [ ? ] of Scrum, where ideas are turned into value.', options: ['heartbeat', 'budget line', 'PAQ', 'Cone'], correct: 'heartbeat', explain: 'The Sprint is the heartbeat of Scrum (3.5).' },
      { id: 'F10Q9', topic: 'SC', q: 'Consider the following statements about the Sprint Retrospective.\n1. The Scrum Team inspects how the last Sprint went regarding individuals, interactions, processes, tools and the Definition of Done\n2. For a one-month Sprint it is timeboxed to a maximum of 3 hours', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Retro purpose and 3-hour maximum are from the Scrum Guide events (3.5).' },
      { id: 'F10Q10', topic: 'SC', q: 'Which of the following are ways the Scrum Master serves the Scrum Team?\n1. Ordering the Product Backlog as a deputy Product Owner\n2. Coaching self-management and cross-functionality\n3. Helping the team focus on high-value Increments that meet the Definition of Done\n4. Removing impediments', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The SM does not take PO accountabilities such as backlog ordering (3.4).' },
      { id: 'F10Q11', topic: 'SC', q: 'What is the Product Goal?', options: ['A future state of the product that serves as a target for the Scrum Team to plan against — the long-term objective', 'The set of tasks on the Team Board for today', 'The Business Sponsor\'s single-figure cost', 'The PAQ consensus score'], correct: 'A future state of the product that serves as a target for the Scrum Team to plan against — the long-term objective', explain: 'Product Goal is the PB\'s commitment and must be fulfilled or abandoned before the next (3.6).' },
      { id: 'F10Q12', topic: 'AF', q: 'Identify the missing words. Parkinson\'s Law, cited as a reason sponsors hesitate to set aside formal contingency, states that work expands to fill the [ ? ].', options: ['time available', 'Definition of Done', 'Solution Backlog', 'Cone of Uncertainty'], correct: 'time available', explain: 'Parkinson\'s Law: work expands to fill the time available (4.2).' },
      { id: 'F10Q13', topic: 'AF', q: 'In the normal AgilePM treatment of the four project variables, which statement is false?', options: ['Quality is intended to become the unofficial variable when pressure rises', 'Time, cost and quality are normally fixed', 'Features are variable, protected from accidental variation by a clear Definition of Done', 'Contingency is managed through MoSCoW rather than by stretching time and cost'], correct: 'Quality is intended to become the unofficial variable when pressure rises', explain: 'Quality becoming variable under pressure is the traditional failure mode AgilePM prevents (4.2).' },
      { id: 'F10Q14', topic: 'AF', q: 'Consider the following statements about Principle 6, Develop Iteratively.\n1. It means working closely with customer/stakeholder to improve the solution from operational feedback in short cycles\n2. Frequent demonstrations, regular reviews, adjustments and embracing change provide transparency, inspection, adaptation and evolution', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Iterative development is feedback-driven improvement, not a single pass (4.3).' },
      { id: 'F10Q15', topic: 'AF', q: 'Under \'Never Compromise Quality\', which group provides quality oversight while the Project Manager makes sure it actually occurs?', options: ['Business Visionary, Solution Architect, Product Owner, and regulatory or other appropriate stakeholders', 'Only the Process Advisor', 'Only Developers who estimated the story', 'Only the investment board'], correct: 'Business Visionary, Solution Architect, Product Owner, and regulatory or other appropriate stakeholders', explain: 'Several roles oversee quality; the PM makes sure oversight actually occurs (4.3).' },
      { id: 'F10Q16', topic: 'AF', q: 'What does AgilePM with Scrum offer that team-level Scrum alone does not?', options: ['A Daily Scrum', 'A project lifecycle with appropriate governance, additional roles for organisational value, techniques for time/budget, and structures for multiple teams', 'A Product Owner', 'A Sprint Goal'], correct: 'A project lifecycle with appropriate governance, additional roles for organisational value, techniques for time/budget, and structures for multiple teams', explain: 'AgilePM wraps Scrum with lifecycle, governance, extra roles and multi-team structure (4.4).' },
      { id: 'F10Q17', topic: 'IN', q: 'Which exact leadership principle is demonstrated when a leader keeps the \'why\' visible so decisions can be tested against it?', options: ['Leaders hide purpose until Deployment', 'Leaders ensure clarity of purpose', 'Leaders replace purpose with a task list', 'Leaders treat purpose as the Project Manager\'s secret'], correct: 'Leaders ensure clarity of purpose', explain: 'Exact wording: leaders ensure clarity of purpose (5.1).' },
      { id: 'F10Q18', topic: 'IN', q: 'Which of these are verbatim Agile Leadership principles rather than look-alikes?\n1. Leadership lives everywhere in the organisation\n2. Leaders foster team accountability\n3. Leaders are stewards of organisational values\n4. Leaders substitute accountability with blame after each Sprint Review', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Blame after a Review contradicts fostering team accountability (5.1).' },
      { id: 'F10Q19', topic: 'IN', q: 'Identify the missing words. Geoff Watts\' first commandment, \'First ask the team\', includes encouraging the team to reflect on [ ? ] situations to deepen learning.', options: ['only the Sponsor\'s', 'real and hypothetical', 'pre-agile 1990s', 'auditor-only'], correct: 'real and hypothetical', explain: 'Ask the team, and use real and hypothetical situations to share insight (5.3.6).' },
      { id: 'F10Q20', topic: 'IN', q: 'Consider the following statements about role sharing.\n1. Roles do not necessarily equate to people; one person may fulfil more than one role\n2. A single role may be shared between multiple people if necessary', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'PAQ Statement 11 and Chapter 5 both allow combining or sharing roles with care (5.3 / 11.2.2.11).' },
      { id: 'F10Q21', topic: 'IN', q: 'Which statement about the three Advisor roles is correct?', options: ['The three are Financial Advisor, Legal Advisor and HR Advisor', 'The three are Business Advisor, Solution Advisor and Process Advisor', 'Advisor is a fourth Scrum Team role alongside PO, SM and Developers', 'Advisors always hold equal authority with the Business Sponsor'], correct: 'The three are Business Advisor, Solution Advisor and Process Advisor', explain: 'Advisor sits outside the project/delivery circles: Business, Solution, Process (5.3–5.4).' },
      { id: 'F10Q22', topic: 'IN', q: 'Which of the following are true of the Project Manager\'s relationships?\n1. With the Business Sponsor: regular, simple, informal contact about progress and challenges\n2. The PM creates the Business Case instead of the Value Ownership roles\n3. With other stakeholders: encourage collaboration and a cohesive valuable solution\n4. The PM and Product Owner own and respond to stakeholder-related issues and risks', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The PM does not create the Business Case; Value Ownership roles do (5.5 / 4.3).' },
      { id: 'F10Q23', topic: 'IN', q: 'A Business Analyst working as a Developer may heavily support which activity?', options: ['Holding the project budget', 'Product Backlog management', 'Cancelling Sprints', 'Choosing the Sponsor\'s single-figure estimate'], correct: 'Product Backlog management', explain: 'A BA-as-Developer may heavily support PO/Ambassador backlog work (5.4).' },
      { id: 'F10Q24', topic: 'CC', q: 'Identify the missing words. Successful community collaboration relies on applying the Nine Principles of Agile Leadership and establishing [ ? ], both with external partners and within the organisation.', options: ['blame clauses', 'agreements', 'single-figure estimates', 'a longer Gantt chart'], correct: 'agreements', explain: 'Community collaboration needs the nine leadership principles plus agreements inside and outside the organisation (6.2).' },
      { id: 'F10Q25', topic: 'CC', q: 'Using the Power/Interest Grid, what is the recommended treatment for a low-power, high-interest stakeholder?', options: ['Closely engage as if they held the budget', 'Keep informed', 'Keep satisfied', 'Monitor with minimum effort'], correct: 'Keep informed', explain: 'Low power / high interest = keep informed (Fig. 6.2).' },
      { id: 'F10Q26', topic: 'CC', q: 'Which of the following are among AgilePM\'s six communication choices?\n1. Replacing all conversation with an unread shared drive\n2. Face-to-face communication\n3. Virtual meetings\n4. Email', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The six are face-to-face, virtual meetings, instant messaging, social media, email and collaborative workspaces (6.3).' },
      { id: 'F10Q27', topic: 'CC', q: 'Consider the following statements about a glossary of terms.\n1. Agile teams often include people from different backgrounds who use specialist terms\n2. If a common straightforward language is not practical, a glossary of key terms and definitions helps prevent misunderstanding', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Shared language first; glossary when specialist terms cannot be avoided (6.3).' },
      { id: 'F10Q28', topic: 'PR', q: 'What decision is the Pre-Project Phase intended to support at portfolio or programme level?', options: ['To deliver the first production Increment', 'To decide whether a project is worth investigating — including whether and when to run Feasibility', 'To baseline fine-grained stories for every later Sprint', 'To complete the Benefits Assessment'], correct: 'To decide whether a project is worth investigating — including whether and when to run Feasibility', explain: 'Pre-Project is a portfolio/programme go/investigate step (7.2).' },
      { id: 'F10Q29', topic: 'PR', q: 'Which of the following correctly distinguish increment types?\n1. A Product Increment is delivered by one or more Agile Delivery Teams\n2. A Solution Increment is what is required for the overarching project outcome and may include training, communications and business change\n3. Product, Solution and Project Increment are three names for the same artefact\n4. A Project Increment is a timeboxed slice of the project, typically bounded by Foundations and a Project Increment Review', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three increment ideas operate at product, solution and project-timebox levels (7.1).' },
      { id: 'F10Q30', topic: 'PR', q: 'Identify the missing words. Delivering a \'[ ? ]\' layer of technology is discouraged because other layers still have to be built before anything is usable.', options: ['vertical', 'horizontal', 'MoSCoW', 'empirical'], correct: 'horizontal', explain: 'Horizontal layers delay value and cause integration problems; prefer a vertical slice (7.5).' },
      { id: 'F10Q31', topic: 'PR', q: 'Consider the following statements about the Terms of Reference.\n1. It is a recommended milestone artefact that justifies the need for a Feasibility Phase\n2. Responsible is the Business Visionary and Accountable is the Business Sponsor', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'ToR: high-level reason to start, governance/portfolio use, R=BV A=BS (App. A / 7.2).' },
      { id: 'F10Q32', topic: 'PR', q: 'By the end of Foundations, what should be confirmed about incremental delivery?', options: ['That no further increments will be allowed', 'A shared understanding of the foundation needed, with enough detail to move safely into the first (or next) Project Increment', 'That every NFR has been coded', 'That Realisation is complete'], correct: 'A shared understanding of the foundation needed, with enough detail to move safely into the first (or next) Project Increment', explain: 'Foundations creates confidence to start Delivery, not a complete detailed design (7.4).' },
      { id: 'F10Q33', topic: 'ES', q: 'Which of the following are true of the Minimum Usable Subset?\n1. It is made up of the Must Have requirements\n2. Won\'t Haves this time are included in the effort total used to calculate the 60% cap\n3. Only Must Haves are guaranteed within the timebox\n4. Should and Could Haves provide the buffer that makes the guarantee possible', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Won\'t Haves are excluded from the effort calculation (9.5).' },
      { id: 'F10Q34', topic: 'ES', q: 'What does Acceptance Criteria answer?', options: ['How the Project Manager will be appraised', 'Who may cancel the Sprint', 'Which PAQ statement failed', 'How we know the story fulfils the user\'s need, provides the required functionality and delivers the intended benefit'], correct: 'How we know the story fulfils the user\'s need, provides the required functionality and delivers the intended benefit', explain: 'AC test the As a / I want / So that of the story (8.2.3).' },
      { id: 'F10Q35', topic: 'ES', q: 'Identify the missing words. Estimating by decomposition is also known as [ ? ] estimating.', options: ['comparative', 't-shirt', 'latent-value', 'bottom-up'], correct: 'bottom-up', explain: 'Decomposition = bottom-up; analogy = comparative (8.3.3).' },
      { id: 'F10Q36', topic: 'ES', q: 'Consider the following statements about financial cases built from MoSCoW.\n1. Worst-case benefits are based on just the Must Haves\n2. Expected-case benefits are based on Musts plus Shoulds, while cost estimates should cover the full scope', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Figure 9.3: worst = Musts; expected = Musts+Shoulds; costs = full scope (9.7).' },
      { id: 'F10Q37', topic: 'ES', q: 'Which role must see that MoSCoW priorities reflect business value so the expected return on investment remains realistic?', options: ['The Project Manager, who assigns every MoSCoW label', 'The Process Advisor', 'The Developers alone, without value-ownership input', 'The Business Visionary'], correct: 'The Business Visionary', explain: 'The BV ensures priorities reflect business value and RoI; the PM does not assign priorities (9.7–9.8).' },
      { id: 'F10Q38', topic: 'ES', q: 'Which of the following are true of Non-Functional Requirements?\n1. They are the same thing as MoSCoW Could Haves\n2. They define how well the solution must perform, usually against quality standards\n3. They may be captured in the Solution Architecture Definition\n4. If discovered too late they may be difficult or impossible to include', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'NFRs are quality/performance constraints, not a MoSCoW category (8.2.2 / 8.2.4).' },
      { id: 'F10Q39', topic: 'PC', q: 'What is a planning horizon in AgilePM?', options: ['The date the investment board next meets', 'The maximum length of a Daily Scrum', 'The outer band of the Cone of Uncertainty expressed as a single figure', 'The project-level timebox period a plan is intended to cover, at an appropriate level of detail'], correct: 'The project-level timebox period a plan is intended to cover, at an appropriate level of detail', explain: 'Plan to sensible horizons: long, medium and short term at matching detail (10.2.2.2).' },
      { id: 'F10Q40', topic: 'PC', q: 'Identify the missing words. When introducing new requirements between increments, it is important not to increase the percentage of [ ? ] effort.', options: ['Won\'t Have', 'workshop', 'glossary', 'Must Have'], correct: 'Must Have', explain: 'Adding Musts eats contingency; keep the Must Have share under control (10.2.3.11).' },
      { id: 'F10Q41', topic: 'PC', q: 'Which of the following are true of burn-up and cumulative flow charts?\n1. A burn-up shows work completed over time\n2. A cumulative flow chart tracks item status (not started, in progress, done) to reveal bottlenecks\n3. Their primary purpose is inspection and adaptation\n4. They should be used to judge and compare team performance', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Charts are working tools, not performance league tables (10.2.3.5).' },
      { id: 'F10Q42', topic: 'PC', q: 'Consider the following statements about Delivery Team Sprint Planning.\n1. It is effectively Topic 3 — how the chosen work will get done — and its output is a Sprint Backlog for each team\n2. PBI MoSCoW priorities are reviewed based on estimated effort, and teams share backlogs so plans stay aligned', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Project Sprint Planning covers why/what; team planning covers how and produces the Sprint Backlog (10.2.3.4.4).' },
      { id: 'F10Q43', topic: 'PC', q: 'Who plays a key role during a Sprint to keep Product and Solution Increments aligned?', options: ['The Business Sponsor, by attending every Daily Scrum', 'The Process Advisor, by estimating story points', 'The investment board, by resetting the DoD nightly', 'The Product Owner, collaborating with the Solution Architect'], correct: 'The Product Owner, collaborating with the Solution Architect', explain: 'The PO guides value in the Sprint and works with the SA so product and solution stay aligned (10.2.3.6).' },
      { id: 'F10Q44', topic: 'RK', q: 'Which of the following are true of risk ownership?\n1. The Business Visionary owns Value Ownership-based risk\n2. The Solution Architect owns Solution Delivery-based risk\n3. The Workshop Facilitator owns all three categories by default\n4. The Project Manager owns Delivery Enablement risk, including organisation, schedule and dependencies', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Risk ownership follows the three role domains (11.1).' },
      { id: 'F10Q45', topic: 'RK', q: 'Consider the following statements about PAQ Statement 17 remedies.\n1. Work with those who own internal and external standards to see which rules are flexible and which are strict\n2. Ensure access to appropriate Business Advisors and build compliance into the Definition of Done and Acceptance Criteria', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Understand the constraint, use Advisors, and put compliance in DoD/AC (11.2.2.17).' },
      { id: 'F10Q46', topic: 'RK', q: 'What is the suggested action if Value Ownership and Solution Delivery cannot collaborate through the project (PAQ Statement 9)?', options: ['Isolate the teams and communicate only through a signed specification', 'Replace the Product Owner with the Process Advisor', 'Convert every Should Have to a Must Have', 'Have Value Ownership attend recommended project events and otherwise be available as needed; use co-location or video/shared workspaces; in split time zones consider Business Analysts in each zone'], correct: 'Have Value Ownership attend recommended project events and otherwise be available as needed; use co-location or video/shared workspaces; in split time zones consider Business Analysts in each zone', explain: 'Full-time standby is often unrealistic; planned events plus as-needed access, with BA bridges across time zones (11.2.2.9).' },
      { id: 'F10Q47', topic: 'GV', q: 'Identify the missing word. Because early estimates sit on Barry Boehm\'s Cone of Uncertainty, AgilePM recommends quoting [ ? ] rather than a lone number.', options: ['penalties', 'job titles', 'blame clauses', 'ranges'], correct: 'ranges', explain: 'The Cone of Uncertainty makes early single figures misleading (12.3.1).' },
      { id: 'F10Q48', topic: 'GV', q: 'Which of the following are true of Project Artefacts in general?\n1. Not every project needs every artefact\n2. Every artefact is mandatory and must be a lengthy narrative document\n3. Artefacts should be produced only if they clearly help the people who will use them\n4. Formality is shaped by contracts, standards and governance but must not reduce agility', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Create artefacts only if they add real value — Highsmith\'s warning applies (App. A).' },
      { id: 'F10Q49', topic: 'GV', q: 'Consider the following statements about the Delivery Plan RACI.\n1. Both Responsible and Accountable are the Project Manager\n2. Both Responsible and Accountable are the Business Visionary', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Delivery Plan: R and A are the Project Manager (App. A).' },
      { id: 'F10Q50', topic: 'GV', q: 'What does a (G) marker on an artefact indicate?', options: ['The artefact is written in green ink', 'The artefact is optional and must never be shown to auditors', 'The artefact replaces the Product Backlog', 'The artefact may also be used in governance activities such as gateways or proving corporate/regulatory standards'], correct: 'The artefact may also be used in governance activities such as gateways or proving corporate/regulatory standards', explain: 'Orange/green/purple show value/solution/management focus; (G) marks governance use (App. A).' },
    ],
  },
]
